934069890396161','','Public','','Auto','财务科目-最新一期会计月','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-08-28 15:45:33','admin','','2026-08-28 15:45:33',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2092934069890396161',NULL,0,'','','','','',NULL),('2093249657967816706','cwkm-jll-all','财务科目-净利率-全部','LIST','','','','Y','','calc','','','2093249329948078082','','Public','','Auto','净利润','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    i.accountmonth AS 会计月,\n    i.indexValue AS 净利率,\ni.indexType AS 财务科目,\n    CASE \n        WHEN i.accountmonth = m.max_month THEN ''最新一期''\n        WHEN i.accountmonth = (m.max_month - (m.max_month % 100)) - 88 THEN ''去年12月''\n        WHEN i.accountmonth = (m.max_month - (m.max_month % 100)) - 188 THEN ''前年12月''\n    END AS 时间类型,\ni.sheetno AS 报表类型,\n i.reportscope AS 报表口径,\n i.reportperiod AS 报表周期\nFROM app_finance_index_info i\nCROSS JOIN (\n    SELECT MAX(accountmonth) AS max_month\n    FROM app_finance_report_info\n    WHERE customername = :entName\n  AND APP_FINANCE_REPORT_INFO.reportno = :reportNo\n) m\nWHERE  i.reportNo = :reportNo\n  AND i.indexType IN (''净利率'')\n  AND i.customername = :entName\n  AND i.accountmonth IN (\n        m.max_month,\n        (m.max_month - (m.max_month % 100)) - 88,\n        (m.max_month - (m.max_month % 100)) - 188 \n      )\nORDER BY i.accountmonth DESC","paramData":[{"id":"2fc0f971-fbc2-fe09-f5ff-6ffe195c1f49","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"cff6663f-325b-0369-8e10-511f03516833","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin','','2026-08-28 16:09:43','admin','','2026-08-28 16:23:15',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2092854620532547586',NULL,0,'','','','','',NULL),('2094250925897101313','jyk-yszk-AI','经验库-应收账款','LIST','','','','Y','','calc','','','2093261500656463873','','Public','','Auto','应收账款和其他应收款','Public','','','',NULL,'','','','','','','','','',NULL,'KnowledgeCode','{"moduleCode":"jyk-yszk-AI","knowledgeName":"经验库-应收账款和其他应收款-AI","withModelSummary":true,"entName":"苏州XX精密机械制造有限公司"}',NULL,NULL,'admin','','2026-08-31 10:28:24','admin','','2026-08-31 14:05:42',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2093261500656463873',NULL,0,'','','','','',NULL),('2093261995966017537','cwkm-yyzk-all','财务科目-应收账款-全部','LIST','','','','Y','','calc','','','2093261500656463873','','Public','','Auto','净利润','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    i.accountmonth AS 会计月,\n    i.indexValue AS 指标本期值,\n    i.changevalue AS 较年初变动金额,\n    i.changerate AS 较年初增幅,\ni.indexType AS 财务科目,\n    CASE \n        WHEN i.accountmonth = m.max_month THEN ''最新一期''\n    END AS 时间类型,\ni.sheetno AS 报表类型,\n i.reportscope AS 报表口径,\n i.reportperiod AS 报表周期\nFROM app_finance_index_info i\nCROSS JOIN (\n    SELECT MAX(accountmonth) AS max_month\n    FROM app_finance_report_info\n    WHERE customername = :entName\n  AND APP_FINANCE_REPORT_INFO.reportno = :reportNo\n) m\nWHERE  i.reportNo = :reportNo\n  AND i.indexType IN (''应收账款'',''其他应收款'',''应收账款和其他应收款合计占总资产比例'')\n  AND i.customername = :entName\n  AND i.accountmonth =\n        m.max_month \nORDER BY i.accountmonth DESC","paramData":[{"id":"2fc0f971-fbc2-fe09-f5ff-6ffe195c1f49","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"cff6663f-325b-0369-8e10-511f03516833","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary