0:26:18','admin',NULL,'2026-09-14 10:26:18',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','',NULL,NULL),('2094613071088660481','cwkm-zxyqcb','财务科目-最新一期财报','LIST','','','','Y','','calc','','','2092937268256911362','','Public','','Auto','财报列表','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT \n      i.accountmonth  as 最新期次会计月,\n      i.reportscope  as 报表口径,\n      i.reportperiod as 报表周期,\n      i.auditflag as 是否审计\nFROM app_finance_report_info i\nWHERE  i.reportNo = :reportNo\nand i.customername=:entName \nand  i.accountmonth = (\n      SELECT MAX(accountmonth) FROM app_finance_report_info WHERE customername = :entName\n  AND APP_FINANCE_REPORT_INFO.reportno = :reportNo\n  )\n\n","paramData":[{"id":"2fc0f971-fbc2-fe09-f5ff-6ffe195c1f49","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"cff6663f-325b-0369-8e10-511f03516833","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin','','2026-09-01 10:27:26','admin','','2026-09-01 13:55:10',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2092854620532547586',NULL,0,'','','','','',NULL),('2094671874022780929','cwkm-yysr-all','财务科目-营业收入-一期一年','LIST','','','','Y','','calc','','','2094670428825006082','','Public','','Auto','净利润','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    i.accountmonth AS 会计月,\n    i.indexValue AS 营业收入,\n i.yoyvalue AS 营业收入同比,\n\n    CASE \n        WHEN i.accountmonth = m.max_month THEN ''最新一期''\n        WHEN i.accountmonth = (m.max_month - (m.max_month % 100)) - 88 THEN ''去年12月''\n    END AS 时间类型,\n i.reportscope AS 报表口径,\n i.reportperiod AS 报表周期\nFROM app_finance_index_info i\nCROSS JOIN (\n    SELECT MAX(accountmonth) AS max_month\n    FROM app_finance_report_info\n    WHERE customername = :entName\n  AND APP_FINANCE_REPORT_INFO.reportno = :reportNo\n) m\nWHERE  i.reportNo = :reportNo\n  AND i.indexType IN (''营业收入'')\n  AND i.customername = :entName\n  AND i.accountmonth IN (\n        m.max_month,\n        (m.max_month - (m.max_month % 100)) - 88\n      )\nORDER BY i.accountmonth DESC","paramData":[{"id":"2fc0f971-fbc2-fe09-f5ff-6ffe195c1f49","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"cff6663f-325b-0369-8e10-511f03516833","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin','','2026-09-01 14:21:06','admin','','2026-09-01 17:15:28',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2092854620532547586',NULL,0,'','','','','',NULL),('2094680875812859906','cwkm-nssr-all','财务科目-纳税销售收入-一期一年-与财务同期','LIST','','','','Y','','calc','','','2094670428825006082','','Public','','Auto','净利润','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    t.taxPeriod AS 纳税期,\n    t.totalsalestax AS 当年累计纳税销售额,\n    t.yoychange AS 较上年同期变动额,\n    t.yoyrate AS 较上年同期同比,\n    t.diffwithreport AS 与本部报表营收相差,\n    t.diffratewithreport AS 与本部报表营收相差幅度,\n    CASE\n        WHEN t.taxPeriod = m.max_month THEN ''最新一期''\n        WHEN t.taxPeriod = (m.max_month - (m.max_month % 100)) - 88 THEN ''上年12月''\n    END AS 时间类型\nFROM app_tax_info t\nCROSS JOIN (\n    SELECT MAX(accountmonth) AS max_month\n    FROM app_finance_report_info\n    WHERE customername = :entName\n  AND APP_FINANCE_REPORT_INFO.reportno = :reportNo\n) m\nWHERE t.reportNo = :reportNo\n  AND t.customername = :entName\n  AND t.taxPeriod IN (\n        m.max_month,\n        (m.max_month - (m.max_month % 100)) - 88\n      )\nORDER BY t.taxPeriod DESC","paramData":[{"id":"2fc0f971-fbc2-fe09-f5ff-6ffe195c1f49","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"cff6663f-325b-0369-8e10-511f03516833","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin','','2026-09-01 14:56:52','admin','','2026-09-01 15:21:52',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2092854620532547586',NULL,0,'','','','','',NULL),('2094691526715191298','cwkm-shzb-bbzx','财务科目-实收资本-本部最新一期','LIST','','','','Y','','calc','','','2094669762413015042','','Public','','Auto','净利润','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    i.accountmonth AS 会计月,\n    i.indexValue AS 实收资本,\n    CASE \n        WHEN i.accountmonth = m.max_month THEN ''最新一期''\n    END AS 时间类型,\n i.reportscope AS 报表口径,\n i.reportperiod AS 报表周期\nFROM app_finance_index_info i\nCROSS JOIN (\n    SELECT MAX(accountmonth) AS max_month\n    FROM app_finance_report_info\n    WHERE customername = :entName\n  AND APP_FINANCE_REPORT_INFO.reportno = :reportNo\n) m\nWHERE  i.reportNo = :reportNo\n  AND i.indexType IN (''实收资本'')\n  AND i.customername = :entName\n  AND i.accountmonth IN (\n        m.max_month\n      )\n   AND i.reportscope=''本部''\nORDER BY i.accountmonth DESC","paramData":[{"id":"2fc0f971-fbc2-fe09-f5ff-6ffe195c1f49","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"cff6663f-325b-0369-8e10-511f03516833","name":"entName","desc":"","type":"1","isSync":"Y"