HAR',NULL,NULL,'Y','N',NULL,'label',NULL,NULL,'20260903212829275',NULL,'Public',NULL,'Auto','授信用信概况','Public','1.0','3',NULL,NULL,NULL,'INPUTTIME','','timestamp without time zone',NULL,'是','入库时间','APP_CREDIT_USE_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-03 21:28:29','admin',NULL,'2026-09-03 21:28:29',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','',NULL,NULL),('2095511482709118977','fydwdbjsxzj','在非银机构对外担保余额较授信增长值','CHAR','','','','Y','','label','','','2095511189548240897','','Public','','Auto','征信指标较授信时变化','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-03 21:57:24','admin','','2026-09-03 21:57:24',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2095511189548240897',NULL,0,'','','','','',NULL),('2095511626166898690','fyjgfzhjzj','在非银机构负债合计较授信增长值','CHAR','','','','Y','','label','','','2095511189548240897','','Public','','Auto','征信指标较授信时变化','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-03 21:57:59','admin','','2026-09-03 21:57:59',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2095511189548240897',NULL,0,'','','','','',NULL),('2095125167568076802','cwkm-chzzts','财务科目-存货周转天数-一期同期授信','LIST','','','','Y','','calc','','','2094670099131740162','','Public','','Auto','净利润','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    i.accountmonth AS 会计月,\n    i.indexValue AS 存货周转天数,\n\n    CASE\n        WHEN i.accountmonth = m.max_month THEN ''最新一期''\n        WHEN i.accountmonth = CAST(CAST(m.max_month AS INTEGER) - 100 AS VARCHAR) THEN ''去年同月''\n        WHEN i.accountmonth = c.credit_month THEN ''授信时''\n    END AS 时间类型,\n\n    i.sheetno AS 报表类型,\n    i.reportscope AS 报表口径,\n    i.reportperiod AS 报表周期\n\nFROM app_finance_index_info i\n\nCROSS JOIN (\n    SELECT MAX(accountmonth) AS max_month\n    FROM app_finance_report_info\n    WHERE customername = :entName\n  AND APP_FINANCE_REPORT_INFO.reportno = :reportNo\n) m\n\nLEFT JOIN (\n    SELECT\n        MAX(r.accountmonth) AS credit_month\n    FROM app_finance_report_info r\n    INNER JOIN app_credit_use_info c\n        ON r.customername = c.customername\n    AND c.reportno = :reportNo\n    AND c.customername = :entName\n    WHERE r.customername = :entName\n      AND r.reportstatus = ''锁定''\n      AND r.accountmonth =\n          CONCAT(\n              CAST(SUBSTRING(c.creditDate, 1, 4) AS INTEGER) - 1,\n              ''12''\n          )\n  AND r.reportno = :reportNo\n) c ON 1 = 1\n\nWHERE i.reportNo = :reportNo\n  AND i.indexType = ''存货周转天数''\n  AND i.customername = :entName\n  AND i.accountmonth IN (\n        m.max_month,\n        CAST(CAST(m.max_month AS INTEGER) - 100 AS VARCHAR),\n        c.credit_month\n      )\n\nORDER BY i.accountmonth DESC","paramData":[{"id":"2fc0f971-fbc2-fe09-f5ff-6ffe195c1f49","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"cff6663f-325b-0369-8e10-511f03516833","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin','','2026-09-02 20:22:20','admin','','2026-09-02 20:23:08',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2092854620532547586',NULL,0,'','','','','',NULL),('2092939130158788609','cwkm-jll-all','财务科目-净利润-全部','LIST','','','','Y','','calc','','','2092935305607852034','','Public','','Auto','净利润','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    i.accountmonth AS 会计月,\n    i.indexValue AS 净利润,\n i.yoyvalue AS 净利润同比,\n\n    CASE \n        WHEN i.accountmonth = m.max_month THEN ''最新一期''\n        WHEN i.accountmonth = (m.max_month - (m.max_month % 100)) - 88 THEN ''去年12月''\n        WHEN i.accountmonth = (m.max_month - (m.max_month % 100)) - 188 THEN ''前年12月''\n        ELSE ''去年同月''   -- 即 max_month - 100\n    END AS 时间类型,\ni.sheetno AS 报表类型,\n i.reportscope AS 报表口径,\n i.reportperiod AS 报表周期\nFROM app_finance_index_info i\nCROSS JOIN (\n    SELECT MAX(accountmonth) AS max_month\n    FROM app_finance_report_info\n    WHERE customername = :entName\n  AND APP_FINANCE_REPORT_INFO.reportno = :reportNo\n) m\nWHERE  i.reportNo = :reportNo\n  AND i.indexType IN (''净利润'')\n  AND i.customername = :entName\n  AND i.accountmonth IN (\n        m.max_month,\n        m.max_month - 100,\n        (m.max_month - (m.max_month % 100)) - 88,\n        (m.max_month - (m.max_month % 100)) - 188 \n      )\nORDER BY i.accountmonth DESC","paramData":[{"id":"2fc0f971-fbc2-fe09-f5ff-6ffe195c1f49","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"cff6663f-325b-0369-8e10-511f03516833","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin','','2026-08-27 19:35:48','admin','','2026-08-28 11:42:47',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2092854620532547586',NULL,0,'','','','','',NULL),('2093253109372497922','cwkm-xslll-all','财务科目-销售利润率-全部','LIST','','','','Y','','calc','','','2093249329948078082','','Public','','Auto','净利润','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    i.accountmonth AS 会计月,\n    i.indexValue AS 销售利润率,\ni.indexType AS 财务科目,\n    CASE \n        WHEN i.accountmonth = m.max_month THEN ''最新一期''\n        WHEN i.accountmonth = (m.max_month - (m.max_month % 100)) - 88 THEN ''去年12月''\n        WHEN i.accountmonth = (m.max_month - (m.max_month % 100)) - 188 THEN ''前年12月''\n    END AS 时间类型,\ni.sheetno AS 报表类型,\n i.reportscope AS 报表口径,\n i.reportperiod AS 报表周期\nFROM app_finance_index_info i\nCROSS JOIN (\n    SELECT MAX(accountmonth) AS max_month\n    FROM app_finance_report_info\n    WHERE customername = :entName\n  AND APP_FINANCE_REPORT_INFO.reportno = :reportNo\n) m\nWHERE  i.reportNo = :reportNo\n  AND i.indexType IN (''销售利润率'')\n  AND i.customername = :entName\n  AND i.accountmonth IN (\n        m.max_month,\n        (m.max_month - (m.max_month % 100)) - 88,\n        (m.max_month - (m.max_month % 100)) - 188 \n      )\nORDER BY i.accountmonth DESC","paramData":[{"id":"2fc0f971-fbc2-fe09-f5ff-6ffe195c1f49","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"cff6663f-325b-0369-8e10-511f03516833","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin','','2026-08-28 16:23:26','admin','','2026-08-28 16:24:20',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2092854620532547586',NULL,0,'','','','','',NULL),('2095062889300832257','cwkm-yszkzzts','财务科目-应收账款周转天数-一期同期授信','LIST','','','','Y','','calc','','','2094670099131740162','','Public','','Auto','净利润','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    i.accountmonth AS 会计月,\n    i.indexValue AS 应收账款周转天数,\n\n    CASE\n        WHEN i.accountmonth = m.max_month THEN ''最新一期''\n        WHEN i.accountmonth = CAST(CAST(m.max_month AS INTEGER) - 100 AS VARCHAR) THEN ''去年同月''\n        WHEN i.accountmonth = c.credit_month THEN ''授信时''\n    END AS 时间类型,\n\n    i.sheetno AS 报表类型,\n    i.reportscope AS 报表口径,\n    i.reportperiod AS 报表周期\n\nFROM app_finance_index_info i\n\nCROSS JOIN (\n    SELECT MAX(accountmonth) AS max_month\n    FROM app_finance_report_info\n    WHERE customername = :entName\n  AND APP_FINANCE_REPORT_INFO.reportno = :reportNo\n) m\n\nLEFT JOIN (\n    SELECT\n        MAX(r.accountmonth) AS credit_month\n    FROM app_finance_report_info r\n    INNER JOIN app_credit_use_info c\n        ON r.customername = c.customername\n    AND c.reportno = :reportNo\n    AND c.customername = :entName\n    WHERE r.customername = :entName\n      AND r.reportstatus = ''锁定''\n      AND r.accountmonth =\n          CONCAT(\n              CAST(SUBSTRING(c.creditDate, 1, 4) AS INTEGER) - 1,\n              ''12''\n          )\n  AND r.reportno = :reportNo\n) c ON 1 = 1\n\nWHERE i.reportNo = :reportNo\n  AND i.indexType = ''应收账款周转天数''\n  AND i.customername = :entName\n  AND i.accountmonth IN (\n        m.max_month,\n        CAST(CAST(m.max_month AS INTEGER) - 100 AS VARCHAR),\n        c.credit_month\n      )\n\nORDER BY i.accountmonth DESC","paramData":[{"id":"2fc0f971-fbc2-fe09-f5ff-6ffe195c1f49","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"cff6663f-325b-0369-8e10-511f03516833","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin','','2026-09-02 16:14:51','admin','','2026-09-02 17:14:24',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2092854620532547586',NULL,0,'','','','','',NULL),('20260903212645270','CREDITDATE','授信日期','CHAR',NULL,NULL,'Y','N',NULL,'label',NULL,NULL,'20260903212645257',NULL,'Public',NULL,'Auto','授信用信概况','Public','1.0','3',NULL,NULL,NULL,'CREDITDATE','32','character varying',NULL,'是','授信日期（授信时点，用于反查报表期）','APP_CREDIT_USE_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-03 21:26:45','admin',NULL,'2