ll},{"id":"cfe523ee-9c4e-4fe4-165e-89fc654715dd","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-03 21:28:29','admin',NULL,'2026-09-03 21:30:58',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2095823069886033922','sfkcqy','是否科创企业','CHAR','','','','Y','','label','','','202609031712181','','Public','','Auto','征信担保人信息','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-04 18:35:33','admin','','2026-09-04 18:35:51',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2095329761296400386',NULL,0,'','','','','',NULL),('2095511189548240897','zxjsxbh','非银机构负债较授信时变化','LIST','','','','Y','','label','','','2095329761296400386','','Public','','Auto','征信情况','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT \n    -- 在非银机构对外担保余额\n    MAX(CASE \n        WHEN i.ZXREPORTNO = g.ZXREPORTNOZX \n        THEN i.NONBANKGUARANTEEBAL \n    END) AS 在非银机构对外担保余额最新值,\n\n    MAX(CASE \n        WHEN i.ZXREPORTNO = g.zxReportNoSX \n        THEN i.NONBANKGUARANTEEBAL \n    END) AS 在非银机构对外担保余额授信时值,\n\n    MAX(CASE \n        WHEN i.ZXREPORTNO = g.ZXREPORTNOZX \n        THEN i.NONBANKGUARANTEEBAL \n    END) - \n    MAX(CASE \n        WHEN i.ZXREPORTNO = g.zxReportNoSX \n        THEN i.NONBANKGUARANTEEBAL \n    END) AS 在非银机构对外担保余额较授信增长值,\n\n\n    -- 在非银机构负债合计\n    MAX(CASE \n        WHEN i.ZXREPORTNO = g.ZXREPORTNOZX \n        THEN i.NONBANKLIABTOTAL \n    END) AS 在非银机构负债合计最新值,\n\n    MAX(CASE \n        WHEN i.ZXREPORTNO = g.zxReportNoSX \n        THEN i.NONBANKLIABTOTAL \n    END) AS 在非银机构负债合计授信时值,\n\n    MAX(CASE \n        WHEN i.ZXREPORTNO = g.ZXREPORTNOZX \n        THEN i.NONBANKLIABTOTAL \n    END) - \n    MAX(CASE \n        WHEN i.ZXREPORTNO = g.zxReportNoSX \n        THEN i.NONBANKLIABTOTAL \n    END) AS 在非银机构负债合计较授信增长值\n\nFROM APP_CREDIT_REPORT_INFO i \nINNER JOIN APP_GUARANTOR_INFO g \n    ON i.ZXREPORTNO IN (g.ZXREPORTNOZX, g.zxReportNoSX) \nWHERE g.reportno = :reportNo \n  AND g.customername = :entName \n  AND g.guarantorname = :guarantorName\n  AND i.reportno = :reportNo\n  AND i.customername = :entName","paramData":[{"id":"2a9152b1-8542-a0db-0c17-d11b59c4d460","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"bd138d27-b35d-1604-20e3-ac40f629e622","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null},{"id":"63fa1a6a-7dec-c102-848f-8cd76318565c","name":"guarantorName","desc":"","type":"1","isSync":"Y","defaultValue":"''泰州公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin','','2026-09-03 21:56:14','admin','','2026-09-04 15:40:29',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2095329761296400386',NULL,0,'','','','','',NULL),('2095516220892712962','fyllzdzzx','非银机构较高利率借款推算利率最大值最新时点','CHAR','','','','Y','','label','','','2095516220817215490','','Public','','Auto','征信指标较授信时变化','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-03 22:16:14','admin','','2026-09-03 22:18:31',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2095511189548240897',NULL,0,'','','','','',NULL),('2095516220896907265','fyllzdzsq','非银机构较高利率借款推算利率最大值上期时点','CHAR','','','','Y','','label','','','2095516220817215490','','Public','','Auto','征信指标较授信时变化','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-03 22:16:14','admin','','2026-09-03 22:19:13',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2095511189548240897',NULL,0,'','','','','',NULL),('2095516220901101569','fyllzdazzl','非银机构较高利率借款推算利率最大值增长率','CHAR','','','','Y','','label','','','2095516220817215490','','Public','','Auto','征信指标较授信时变化','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-03 22:16:14','admin','','2026-09-03 22:19:36',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2095511189548240897',NULL,0,'','','','','',NULL),('2095779561074601985','fydwdbsx','在非银机构对外担保余额授信时值','CHAR','','','','Y','','label','','','2095511189548240897','','Public','','Auto','非银机构负债较授信时变化','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-04 15:42:39','admin','','2026-09-04 15:42:39',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2095511189548240897',NULL,0,'','','','','',NULL),('2095786938666594306','cxriqizuixin','最新征信查询日期','CHAR','','','','Y','','label','','','2095518390996242433','','Public','','Auto','流贷金额三期值','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-04 16:11:58','admin','','2026-09-04 16:11:58',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2095518390996242433',NULL,0,'','','','','',NULL),('2097290740775268353','xindaifaren','信贷系统法人','CHAR','','','','Y','','label','','','2097290064745738241','','Public','','Auto','信贷法人与工商法人一致性对比','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-08 19:47:33','admin','','2026-09-08 19:47:33',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2097290064745738241',NULL,0,'','','','','',NULL),('2097291376233295873','farenyizhihu','是否一致','CHAR','','','','Y','','label','','','2097290064745738241','','Public','','Auto','信贷法人与工商法人一致性对比','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-08 19:50:04','admin','','2026-09-08 19:50:04',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2097290064745738241',NULL,0,'','','','','',NULL),('2097495446613143553','gdjmgq','是否有股东假冒国企','CHAR','','','','Y','','label','','','2097494825562550273','','Public','','Auto','借款人及股东假冒国企','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-09 09:20:58','admin','','2026-09-09 09:20:58',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2097494825562550273',NULL,0,'','','','','',NULL),('2095516220817215490','fyjsllzdzbhsq','非银机构较高利率借款推算利率最大值较上期变化','LIST','','','','Y','','label','','','2095329761296400386','','Public','','Auto','征信情况','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT \n    MAX(CASE WHEN i.ZXREPORTNO = g.ZXREPORTNOZX THEN i.NONBANKHIGHRATELOAN END) AS 非银机构较高利率借款推算利率最大值最新时点,\n    \n    MAX(CASE WHEN i.ZXREPORTNO = g.zxReportNoSQ THEN i.NONBANKHIGHRATELOAN END) AS 非银机构较高利率借款推算利率最大值上期时点,\n    \n    CASE\n        WHEN MAX(CASE WHEN i.ZXREPORTNO = g.zxReportNoSQ THEN i.NONBANKHIGHRATELOAN END) IS NULL\n          OR MAX(CASE WHEN i.ZXREPORTNO = g.zxReportNoSQ THEN i.NONBANKHIGHRATELOAN END) = 0\n        THEN NULL\n        ELSE (\n            MAX(CASE WHEN i.ZXREPORTNO = g.ZXREPORTNOZX THEN i.NONBANKHIGHRATELOAN END)\n            - MAX(CASE WHEN i.ZXREPORTNO = g.zxReportNoSQ THEN i.NONBANKHIGHRATELOAN END)\n        )\n        / MAX(CASE WHEN i.ZXREPORTNO = g.zxReportNoSQ THEN i.NONBANKHIGHRATELOAN END) * 100\n    END AS 非银机构较高利率借款推算利率最大值增长率\n\nFROM APP_CREDIT_REPORT_INFO i \nINNER JOIN APP_GUARANTOR_INFO g \n    ON i.ZXREPORTNO IN (g.ZXREPORTNOZX, g.zxReportNoSQ) \nWHERE g.reportno = :reportNo \n  AND g.customername = :entName \n  AND g.guarantorname = :guarantorName\n  AND i.reportno = :reportNo\n  AND i.customername = :entName","paramData":[{"id":"2a9152b1-8542-a0db-0c17-d11b59c4d460","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"bd138d27-b35d-1604-20e3-ac40f629e622","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null},{"id":"63fa1a6a-7dec-c102-848f-8cd76318565c","name":"guarantorName","desc":"","type":"1","isSync":"Y","defaultValue":"''泰州公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin','','2026-09-03 22:16:14','admin','','2026-09-03 22:18:03',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2095329761296400386',NULL,0,'','','','','',NULL),('20260904090943315','INDUSTRYTYPE','行业分类','CHAR',NULL,NULL,'Y','N',NULL,'label',NULL,NULL,'20260904090943307',NULL,'Public',NULL,'Auto','信贷系统客户基本情况','Public','1.0','3',NULL,NULL,NULL,'INDUSTRYTYPE','64','character varying',NULL,'是','行业分类（码值：GB/T 4754 行业代码，码值待确认）','APP_CUSTOMER_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-04 09:09:43','admin',NULL,'2026-09-04 09:09:43',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','',NULL,NULL),('2095779648311930882','fyfzsx','在非银机构负债合计授信时值','CHAR','','','','Y','','label','','','2095511189548240897','','Public','','Auto','非银机构负债较授信时变化','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-04 15:43:00','admin','','2026-09-04 15:45:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2095329761296400386',NULL,0,'','','','','',NULL),('20260904090943308','ID','ID','CHAR',NULL,NULL,'N','N',NULL,'label',NULL,NULL,'20260904090943307',NULL,'Public',NULL,'Auto','信贷系统客户基本情况','Public','1.0','3',NULL,NULL,NULL,'ID','64,0','bigint',NULL,'否','','APP_CUSTOMER_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-04 09:09:43','admin',NULL,'2026-09-04 09:09:43',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','',NULL,NULL),('20260904090943309','REPORTNO','报告编号','CHAR',NULL,NULL,'N','N',NULL,'label',NULL,NULL,'20260904090943307',NULL,'Public',NULL,'Auto','信贷系统客户基本情况','Public','1.0','3',NULL,NULL,NULL,'REPORTNO','64','character varying',NULL,'否','报告编号','APP_CUSTOMER_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-04 09