NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-04 15:00:44','admin','','2026-09-04 15:05:06',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2094715522143825922',NULL,0,'','','','','',NULL),('2095770209135636482','cwkm-cqjk-bbzx','财务科目-本部长期借款-最新','LIST','','','','Y','','calc','','','2094669956173082625','','Public','','Auto','净利润','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n i.indexValue AS 本部长期借款\nFROM app_finance_index_info i\nCROSS JOIN (\n    SELECT MAX(accountmonth) AS max_month\n    FROM app_finance_report_info\n    WHERE customername = :entName\n  AND APP_FINANCE_REPORT_INFO.reportno = :reportNo\n) m\nWHERE  i.reportNo = :reportNo\n  AND i.indexType IN (''长期借款'')\nAND i.reportscope = ''本部''\n  AND i.customername = :entName\n  AND i.accountmonth IN (\n        m.max_month  )","paramData":[{"id":"2fc0f971-fbc2-fe09-f5ff-6ffe195c1f49","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"cff6663f-325b-0369-8e10-511f03516833","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin','','2026-09-04 15:05:30','admin','','2026-09-04 15:21:33',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2092854620532547586',NULL,0,'','','','','',NULL),('20260903201033213','APP_GUARANTOR_CREDIT_INFO','最新一期征信情况-自然人','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2095329761296400386',NULL,'Public',NULL,'Auto','征信情况','Public','1.0','3',NULL,NULL,NULL,'APP_GUARANTOR_CREDIT_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_GUARANTOR_CREDIT_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n\n    i.ID AS ID,\n\n    i.REPORTNO AS 报告编号,\n\n    i.CUSTOMERID AS 客户编号,\n\n    i.CUSTOMERNAME AS 客户名称,\n\n    i.GUARANTORNAME AS 担保人,\n\n    i.QUERYTIME AS 征信查询时间,\n\n    i.ZXREPORTNO AS 征信报告记录号,\n\n    i.TOTALLOANBAL AS 贷款余额合计,\n\n    i.OPERATELOANBAL AS 经营性贷款余额合计,\n\n    i.CONSUMELOANBAL AS 消费类贷款余额合计,\n\n    i.HOUSELOANBAL AS 住房类贷款余额合计,\n\n    i.OTHERLOANBAL AS 其他贷款余额合计,\n\n    i.TOTALLOANCOUNT AS 贷款机构数,\n\n    i.OPERATELOANCOUNT AS 经营性贷款机构数,\n\n    i.CONSUMELOANCOUNT AS 消费类贷款机构数,\n\n    i.HOUSELOANCOUNT AS 住房类贷款机构数,\n\n    i.OTHERLOANCOUNT AS 其他贷款机构数,\n\n    i.BADBAL AS 呆账余额,\n\n    i.BZCBAL AS 被追偿余额,\n\n    i.LOANCURRENTOVERDUE AS 贷款当前逾期总金额,\n\n    i.CARDCURRENTOVERDUE AS 贷记卡当前逾期总金额,\n\n    i.GUARANTEEOVERDUEAMT AS 对外担保相关还款责任当前逾期金额,\n\n    i.NONBANKGUARANTEEBAL AS 在非银机构对外担保余额,\n\n    i.NONBANKHIGHRATELOAN AS 非银机构较高利率借款推算利率最大值,\n\n    i.GUARANTEEABNORMALBAL AS 对外担保相关还款责任五级分类非正常余额,\n\n    i.EXTENDBAL AS 展期债务余额,\n\n    i.DELAYBAL AS 落实金融困等政策银行主动延期债务余额,\n\n    i.CREDITABNORMALBAL AS 未结清信贷五级分类非正常余额,\n\n    i.ACCTABNORMALBAL AS 未结清账户状态非正常余额,\n\n    i.CARDABNORMALBAL AS 未销户贷记卡账户状态非正常余额,\n\n    i.GUARANTEEHKABNORMALBAL AS 对外担保相关还款责任还款状态非正常余额,\n\n    i.CREDITUSERATE AS 信用卡使用率,\n\n    i.INPUTTIME AS 入库时间,\n\n    i.GUARANTORID AS 担保人客户编号,\n\n    i.NONBANKLIABTOTAL AS 在非银机构负债合计,\n\n    i.LOANQUERY12M AS 近一年贷款审批征信查询次数,\n\n    i.LOANQUERY6M AS 近6个月贷款审批征信查询次数,\n\n    i.CARDQUERY6M AS 近6个月信用卡审批征信查询次数,\n\n    i.LOANQUERY3M AS 近3个月贷款审批征信查询次数,\n\n    i.CARDQUERY12M AS 近一年信用卡审批征信查询次数,\n\n    i.CARDQUERY3M AS 近3个月信用卡审批征信查询次数,\n\n    i.SELFQUERY1M AS 近1个月本人查询征信查询次数,\n\n    CURRENT_DATE - CAST(i.QUERYTIME AS DATE) AS 最新一期征信查询时间距当前时间天数\n\nFROM APP_GUARANTOR_CREDIT_INFO i\n\nINNER JOIN APP_GUARANTOR_INFO g\n\n    ON i.ZXREPORTNO = g.ZXREPORTNOZX\n\nWHERE g.reportno = :reportNo\n\n  AND g.customername = :entName\n\n  AND g.guarantorname = :guarantorName\n  AND i.reportno = :reportNo\n  AND i.customername = :entName","paramData":[{"id":"5ff1afc1-152f-3f24-67ee-6b7b03838352","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"6a9d5ed2-eea7-5953-1b34-0a8566ad987a","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null},{"id":"a6a33a63-43f8-df63-34e5-9b804fdb41b5","name":"guarantorName","desc":"","type":"1","isSync":"Y","defaultValue":"''张三''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-03 20:10:33','admin',NULL,'2026-09-04 17:01:18',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('202609031712181','APP_GUARANTOR_INFO','征信担保人信息','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2095329761296400386',NULL,'Public',NULL,'Auto','征信情况','Public','1.0','3',NULL,NULL,NULL,'APP_GUARANTOR_INFO',NULL,NULL,NULL,NULL,NULL,'APP_GUARANTOR_INFO','2092788284460699650',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    i.ZXREPORTNOZX AS 征信报告记录号最新,\n    i.ZXREPORTNOSQ AS 征信报告记录号上期,\n    i.ZXREPORTNOSX AS 征信报告记录号授信,\n    i.ID AS ID,\n    i.EDUCATION AS 学历,\n    i.GUARANTORNAME AS 担保人,\n    i.GUARANTORTYPE AS 担保人类型,\n    i.ISSTATEOWNED AS 是否国有担保,\n    i.INPUTTIME AS 入库时间,\n    i.GUARANTORID AS 担保人客户编号,\n    i.SUBJECTTYPE AS 主体类型,\n    i.CUSTOMERID AS 客户编号,\n    i.CUSTOMERNAME AS 客户名称,\n    c.isTechCompany AS 是否科创企业,\n    c.actualController AS 实际控制人,\n    CASE\n        WHEN c.actualController IS NOT NULL\n             AND POSITION(i.GUARANTORNAME IN c.actualController) > 0\n        THEN ''是''\n        ELSE ''否''\n    END AS 担保人是否是实控人,\n    u.creditSum AS 授信金额,\n    i.REPORTNO AS 报告编号\nFROM APP_GUARANTOR_INFO i\nLEFT JOIN APP_CUSTOMER_INFO c\n    ON i.customerid = c.customerId\n    AND i.customername = c.customerName\n    AND c.reportno = :reportNo\n    AND c.customername = :entName\nLEFT JOIN APP_CREDIT_USE_INFO u\n    ON i.reportno = u.reportNo\n    AND i.customerid = u.customerId\n    AND i.customername = u.customername\n    AND u.reportno = :reportNo\n    AND u.customername = :entName\nWHERE i.reportno = :reportNo\n  AND i.customername = :entName\n  AND i.guarantorname= :guarantorName","paramData":[{"id":"a91d40f8-c3cf-4c27-d73e-dbbe285a567d","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"2a99a756-74a6-70de-0f45-8a3e5071c7e8","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null},{"id":"987a7d66-787c-728d-c214-a3e0085b5fac","name":"guarantorName","desc":"","type":"1","isSync":"Y","defaultValue":"''张三''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-03 17:12:18','admin',NULL,'2026-09-04 18:38:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2095518390996242433','ldjesq','流贷金额三期值','LIST','','','','Y','','label','','','2095329761296400386','','Public','','Auto','征信情况','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT   \n    MAX(CASE WHEN i.ZXREPORTNO = g.ZXREPORTNOZX THEN i.WORKINGCAPITALLOANBAL END) AS 流贷金额最新时点,  \n     \n    MAX(CASE WHEN i.ZXREPORTNO = g.zxReportNoSQ THEN i.WORKINGCAPITALLOANBAL END) AS 流贷金额上期时点,  \n     \n    MAX(CASE WHEN i.ZXREPORTNO = g.zxReportNoSX THEN i.WORKINGCAPITALLOANBAL END) AS 流贷金额授信时点,\n\n    MAX(CASE WHEN i.ZXREPORTNO = g.ZXREPORTNOZX THEN i.WORKINGCAPITALLOANBAL END)\n    - MAX(CASE WHEN i.ZXREPORTNO = g.zxReportNoSQ THEN i.WORKINGCAPITALLOANBAL END) AS 流贷金额最新较上期增加值,\n\n    MAX(CASE WHEN i.ZXREPORTNO = g.ZXREPORTNOZX THEN i.WORKINGCAPITALLOANBAL END)\n    - MAX(CASE WHEN i.ZXREPORTNO = g.zxReportNoSX THEN i.WORKINGCAPITALLOANBAL END) AS 流贷金额最新较授信增加值,\n\n    MAX(CASE WHEN i.ZXREPORTNO = g.ZXREPORTNOZX THEN i.QUERYTIME END) AS 最新征信查询日期,\n\n    MAX(CASE WHEN i.ZXREPORTNO = g.zxReportNoSQ THEN i.QUERYTIME END) AS 上期征信查询日期,\n\n    MAX(CASE WHEN i.ZXREPORTNO = g.zxReportNoSX THEN i.QUERYTIME END) AS 授信征信查询日期\n  \nFROM APP_CREDIT_REPORT_INFO i   \nINNER JOIN APP_GUARANTOR_INFO g   \n    ON i.ZXREPORTNO IN (g.ZXREPORTNOZX, g.zxReportNoSQ, g.zxReportNoSX)   \nWHERE g.reportno = :reportNo   \n  AND g.customername = :entName   \n  AND g.guarantorname = :guarantorName\n  AND i.reportno = :reportNo\n  AND i.customername = :entName","paramData":[{"id":"2a9152b1-8542-a0db-0c17-d11b59c4d460","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"bd138d27-b35d-1604-20e3-ac40f629e622","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null},{"id":"63fa1a6a-7dec-c102-848f-8cd76318565c","name":"guarantorName","desc":"","type":"1","isSync":"Y","defaultValue":"''泰州公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin','','2026-09-03 22:24:51','admin','','2026-09-04 16:15:12',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2095329761296400386',NULL,0,'','','','','',NULL),('2095827833998815233','fydwdbjsxzj','在非银机构对外担保余额较授信增长值','CHAR','','','','Y','','label','','','2095827833919123457','','Public','','Auto','征信指标较授信时变化','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-04 18:54:28','admin','','2026-09-04 18:54:28',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2095511189548240897',NULL,0,'','','','','',NULL),('2095818594752409601','fyllzdzzx','非银机构较高利率借款推算利率最大值最新时点','CHAR','','','','Y','','label','','','2095818594668523522','','Public','','Auto','征信指标较授信时变化','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-04 18:17:46','admin','','2026-09-04 18:17:46',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2095511189548240897',NULL,0,'','','','','',NULL),('2095818594756603906','fyllzdzsq','非银机构较高利率借款推算利率最大值上期时点','CHAR','','','','Y','','label','','','2095818594668523522','','Public','','Auto','征信指标较授信时变化','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-04 18:17:46','admin','','2026-09-04 18:17:46',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2095511189548240897',NULL,0,'','','','','',NULL),('2095818594756603907','fyllzdazzl','非银机构较高利率借款推算利率最大值增长率','CHAR','','','','Y','','label','','','2095818594668523522','','Public','','Auto','征信指标较授信时变化','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-04 18:17:46','admin','','2026-09-04 18:17:46',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2095511189548240897',NULL,0,'','','','','',NULL),('2095818594668523522','fyjsllzdzbhsqgr','非银机构较高利率借款推算利率最大值较上期变化-自然人','LIST','','','','Y','','label','','','2095329761296400386','','Public','','Auto','征信情况','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT \n    MAX(CASE WHEN i.ZXREPORTNO = g.ZXREPORTNOZX THEN i.NONBANKHIGHRATELOAN END) AS 非银机构较高利率借款推算利率最大值最新时点,\n    \n    MAX(CASE WHEN i.ZXREPORTNO = g.zxReportNoSQ THEN i.NONBANKHIGHRATELOAN END) AS 非银机构较高利率借款推算利率最大值上期时点,\n    \n    CASE\n        WHEN MAX(CASE WHEN i.ZXREPORTNO = g.zxReportNoSQ THEN i.NONBANKHIGHRATELOAN END) IS NULL\n          OR MAX(CASE WHEN i.ZXREPORTNO = g.zxReportNoSQ THEN i.NONBANKHIGHRATELOAN END) = 0\n        THEN NULL\n        ELSE (\n            MAX(CASE WHEN i.ZXREPORTNO = g.ZXREPORTNOZX THEN i.NONBANKHIGHRATELOAN END)\n            - MAX(CASE WHEN i.ZXREPORTNO = g.zxReportNoSQ THEN i.NONBANKHIGHRATELOAN END)\n        )\n        / MAX(CASE WHEN i.ZXREPORTNO = g.zxReportNoSQ THEN i.NONBANKHIGHRATELOAN END) * 100\n    END AS 非银机构较高利率借款推算利率最大值增长率\n\nFROM app_guarantor_credit_info  i \nINNER JOIN APP_GUARANTOR_INFO g \n    ON i.ZXREPORTNO IN (g.ZXREPORTNOZX, g.zxReportNoSQ) \nWHERE g.reportno = :reportNo \n  AND g.customername = :entName \n  AND g.guarantorname = :guarantorName\n  AND i.reportno = :reportNo\n  AND i.customername = :entName","paramData":[{"id":"2a9152b1-8542-a0db-0c17-d11b59c4d460","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"bd138d27-b35d-1604-20e3-ac40f629e622","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null},{"id":"63fa1a6a-7dec-c102-848f-8cd76318565c","name":"guarantorName","desc":"","type":"1","isSync":"Y","defaultValue":"''张三''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin','','2026-09-04 18:17:46','admin','','2026-09-04 18:19:12',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2095329761296400386',NULL,0,'','','','','',NULL),('2095827834003009538','fyjgfzhjzj','在非银机构负债合计较授信增长值','CHAR','','','','Y','','label','','','2095827833919123457','','Public','','Auto','征信指标较授信时变化','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-04 18:54:28','admin','','2026-09-04 18:54:28',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2095511189548240897',NULL,0,'','','','','',NULL),('2095827834003009539','fydwdbzx','在非银机构对外担保余额最新值','CHAR','','','','Y','','label','','','2095827833919123457','','Public','','Auto','征信指标较授信时变化','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-04 18:54:28','admin','','2026-09-04 18:54:28',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2095511189548240897',NULL,0,'','','','','',NULL);
INSERT INTO index_params (paramno,paramid,paramname,paramtype,codemethod,codeno,required,readonly,defaultformat,inputmethod,fromparamno,defaultvalue,parentparamno,publicparamstatus,modelno,initmethod,datamethod,parentparamname,reportversion,versionno,paramsource,charttype,sortno,placeholder,acturecolumn,columnlength,columntype,columnremark,columnisnull,columncomment,columnfromtable,columnfromdatasource,otherconfig,scripttype,script,validators,chartinitmethod,inputuserid,inputorgid,inputtime,updateuserid,updateorgid,updatetime,supplierid,intfno,intfparams,intffield,intffieldtype,structure,extendfield,otherno,count_field,is_online,metric_intro,data_unit,data_example,data_type,data_content_parse,paramkey) VALUES ('2095827833919123457','zxjsxbhggr','非银机构负债较授信时变化-自然人','LIST','','','','Y','','label','','','2095329761296400386','','Public','','Auto','征信情况','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT \n    -- 在非银机构对外担保余额\n    MAX(CASE \n        WHEN i.ZXREPORTNO = g.ZXREPORTNOZX \n        THEN i.NONBANKGUARANTEEBAL \n    END) AS 在非银机构对外担保余额最新值,\n\n    MAX(CASE \n        WHEN i.ZXREPORTNO = g.zxReportNoSX \n        THEN i.NONBANKGUARANTEEBAL \n    END) AS 在非银机构对外担保余额授信时值,\n\n    MAX(CASE \n        WHEN i.ZXREPORTNO = g.ZXREPORTNOZX \n        THEN i.NONBANKGUARANTEEBAL \n    END) - \n    MAX(CASE \n        WHEN i.ZXREPORTNO = g.zxReportNoSX \n        THEN i.NONBANKGUARANTEEBAL \n    END) AS 在非银机构对外担保余额较授信增长值,\n\n\n    -- 在非银机构负债合计\n    MAX(CASE \n        WHEN i.ZXREPORTNO = g.ZXREPORTNOZX \n        THEN i.NONBANKLIABTOTAL \n    END) AS 在非银机构负债合计最新值,\n\n    MAX(CASE \n        WHEN i.ZXREPORTNO = g.zxReportNoSX \n        THEN i.NONBANKLIABTOTAL \n    END) AS 在非银机构负债合计授信时值,\n\n    MAX(CASE \n        WHEN i.ZXREPORTNO = g.ZXREPORTNOZX \n        THEN i.NONBANKLIABTOTAL \n    END) - \n    MAX(CASE \n        WHEN i.ZXREPORTNO = g.zxReportNoSX \n        THEN i.NONBANKLIABTOTAL \n    END) AS 在非银机构负债合计较授信增长值\n\nFROM app_guarantor_credit_info i \nINNER JOIN APP_GUARANTOR_INFO g \n    ON i.ZXREPORTNO IN (g.ZXREPORTNOZX, g.zxReportNoSX) \nWHERE g.reportno = :reportNo \n  AND g.customername = :entName \n  AND g.guarantorname = :guarantorName\n  AND i.reportno = :reportNo\n  AND i.customername = :entName","paramData":[{"id":"2a9152b1-8542-a0db-0c17-d11b59c4d460","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"bd138d27-b35d-1604-20e3-ac40f629e622","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null},{"id":"63fa1a6a-7dec-c102-848f-8cd76318565c","name":"guarantorName","desc":"","type":"1","isSync":"Y","defaultValue":"''张三''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin','','2026-09-04 18:54:28','admin','','2026-09-04 19:03:44',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2095329761296400386',NULL,0,'','','','','',NULL),('20260903195039160','APP_CREDIT_REPORT_INFO','最新一期征信情况-企业','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2095329761296400386',NULL,'Public',NULL,'Auto','征信情况','Public','1.0','3',NULL,NULL,NULL,'APP_CREDIT_REPORT_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_CREDIT_REPORT_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    i.ID,\n    i.REPORTNO,\n    i.CUSTOMERID,\n    i.CUSTOMERNAME,\n    u.creditSum AS 授信金额,\n    i.QUERYTIME,\n    TO_CHAR(CURRENT_DATE, ''YYYY-MM-DD'') AS \"当前时间\",\n    CURRENT_DATE - CAST(i.QUERYTIME AS DATE) AS \"最新一期征信查询时间距当前时间天数\",\n    i.ZXREPORTNO,\n    i.EXPIREDATE,\n    i.OVERDUETOTAL,\n    i.ATTENTIONCREDITBAL,\n    i.BADCREDITBAL,\n    i.ATTENTIONGUARANTEEBAL,\n    i.BADGUARANTEEBAL,\n    i.GUARANTEEOVERDUETOTAL,\n    i.GUARANTEEATTENTIONBAL,\n    i.GUARANTEEBADBAL,\n    i.EXTENDDEBTBAL,\n    i.RESTRUCTUREDEBTBAL,\n    i.RENEWDEBTBAL,\n    i.TRANSFERDEBTBAL,\n    i.NEWOLDDEBTBAL,\n    i.NONBANKLIABTOTAL,\n    i.NONBANKHIGHRATELOAN,\n    i.INPUTTIME,\n    i.SUBJECTTYPE,\n    i.GUARANTORID,\n    i.GUARANTORNAME,\n    i.NONBANKGUARANTEEBAL,\n    i.WORKINGCAPITALLOANBAL,\n    i.WORKINGCAPITALLOAN1YBAL,\n    i.LOANBANKORGCOUNT,\n    i.GUARANTEEBANKORGCOUNT,\n    i.CREDITSHORTTERMDIFF,\n    i.CREDITLONGTERMDIFF,\n    i.CREDITDEBTDEVIATION,\n    i.GUARANTEENETASSET,\n    i.GUARANTEEBALANCEEXBANK,\n    i.SHORTTERMLOANORGCOUNT,\n    i.MIDLONGTERMLOANORGCOUNT,\n    i.REVOLVINGOVERDRAFTORGCOUNT,\n    i.DISCOUNTORGCOUNT,\n    i.BANKACCEPTANCEBILLORGCOUNT,\n    i.LETTEROFCREDITORGCOUNT,\n    i.BANKGUARANTEEORGCOUNT,\n    i.OTHERGUARANTEETRADEORGCOUNT,\n    i.SHORTTERMLOANBAL,\n    i.MIDLONGTERMLOANBAL,\n    i.REVOLVINGOVERDRAFTBAL,\n    i.DISCOUNTBAL,\n    i.BANKACCEPTANCEBILLBAL,\n    i.LETTEROFCREDITBAL,\n    i.BANKGUARANTEEBAL,\n    i.OTHERGUARANTEETRADEBAL\nFROM APP_CREDIT_REPORT_INFO i\nINNER JOIN APP_GUARANTOR_INFO g\n    ON i.ZXREPORTNO = g.ZXREPORTNOZX\nLEFT JOIN APP_CREDIT_USE_INFO u\n    ON i.REPORTNO = u.REPORTNO\n    AND i.CUSTOMERID = u.CUSTOMERID\n    AND i.CUSTOMERNAME = u.CUSTOMERNAME\n    AND u.reportno = :reportNo\n    AND u.customername = :entName\nWHERE g.reportno = :reportNo\n  AND g.customername = :entName\n  AND g.guarantorname = :guarantorName\n  AND i.reportno = :reportNo\n  AND i.customername = :entName","paramData":[{"id":"45b00f5a-ba9a-28b9-86eb-8cd38120e4e1","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"b362361f-6e31-fb0c-3b0d-c64b452b89ec","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null},{"id":"fdf026be-ed28-ee8b-93cf-961245bb4dc2","name":"guarantorName","desc":"","type":"1","isSync":"Y","defaultValue":"''泰州公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-03 19:50:39','admin',NULL,'2026-09-07 09:32:38',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2095833592224559106','fydwdbjsxzj','剔除我行对外担保最新值','CHAR','','','','Y','','label','','','2095833592136478721','','Public','','Auto','剔除我行对外担保较授信时变化','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-04 19:17:21','admin','','2026-09-04 19:21:45',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2095511189548240897',NULL,0,'','','','','',NULL),('2095833592224559107','fyjgfzhjzj','剔除我行对外担保授信值','CHAR','','','','Y','','label','','','2095833592136478721','','Public','','Auto','剔除我行对外担保较授信时变化','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-04 19:17:21','admin','','2026-09-04 19:22:04',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2095511189548240897',NULL,0,'','','','','',NULL),('2095833592228753410','fydwdbzx','剔除我行对外担保较授信增长率','CHAR','','','','Y','','label','','','2095833592136478721','','Public','','Auto','剔除我行对外担保较授信时变化','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-04 19:17:21','admin','','2026-09-04 19:22:28',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2095511189548240897',NULL,0,'','','','','',NULL),('2096859466315083778','sfczxzql','押品是否存在限制权力','LIST','','','','Y','','calc','','','2095687266304331778','','Public','','Auto','信贷系统客户基本情况','Public','','','',NULL,'','','','','','','','','',NULL,'KnowledgeCode','{"moduleCode":"jyk-sfczxianzhiquanli","knowledgeName":"经验库过程-是否存在限制权利","withModelSummary":true,"entName":"苏州XX精密机械制造有限公司","clrId":"002"}',NULL,NULL,'admin','','2026-09-07 15:13:49','admin','','2026-09-07 15:16:27',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2094355937138651137',NULL,0,'','','','','',NULL),('2096860288579022849','sfczsywdcdy','押品是否存在抵押物多次抵押','LIST','','','','Y','','calc','','','2095687266304331778','','Public','','Auto','信贷系统客户基本情况','Public','','','',NULL,'','','','','','','','','',NULL,'KnowledgeCode','{"moduleCode":"jyk-sfczxianzhidwwdcdy","knowledgeName":"经验库过程-是否存在抵押物多次抵押","withModelSummary":true,"entName":"苏州XX精密机械制造有限公司","clrId":"001"}',NULL,NULL,'admin','','2026-09-07 15:17:05','admin','','2026-09-07 15:18:01',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2094355937138651137',NULL,0,'','','','','',NULL),('2095833592136478721','tcwhdwdb_copy','剔除我行对外担保较授信时变化','LIST','','','','Y','','label','','','2095329761296400386','','Public','','Auto','征信情况','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    -- 剔除我行对外担保最新值\n    MAX(\n        CASE\n            WHEN i.ZXREPORTNO = g.ZXREPORTNOZX\n            THEN i.GUARANTEEBALANCEEXBANK\n        END\n    ) AS 剔除我行对外担保最新值,\n\n    -- 剔除我行对外担保授信值\n    MAX(\n        CASE\n            WHEN i.ZXREPORTNO = g.zxReportNoSX\n            THEN i.GUARANTEEBALANCEEXBANK\n        END\n    ) AS 剔除我行对外担保授信值,\n\n    -- 剔除我行对外担保较授信增长率\n    CASE\n        WHEN MAX(\n            CASE\n                WHEN i.ZXREPORTNO = g.zxReportNoSX\n                THEN i.GUARANTEEBALANCEEXBANK\n            END\n        ) IS NULL\n        OR MAX(\n            CASE\n                WHEN i.ZXREPORTNO = g.zxReportNoSX\n                THEN i.GUARANTEEBALANCEEXBANK\n            END\n        ) = 0\n        THEN NULL\n\n        ELSE\n            (\n                MAX(\n                    CASE\n                        WHEN i.ZXREPORTNO = g.ZXREPORTNOZX\n                        THEN i.GUARANTEEBALANCEEXBANK\n                    END\n                )\n                -\n                MAX(\n                    CASE\n                        WHEN i.ZXREPORTNO = g.zxReportNoSX\n                        THEN i.GUARANTEEBALANCEEXBANK\n                    END\n                )\n            )\n            /\n            MAX(\n                CASE\n                    WHEN i.ZXREPORTNO = g.zxReportNoSX\n                    THEN i.GUARANTEEBALANCEEXBANK\n                END\n            )\n            * 100\n    END AS 剔除我行对外担保较授信增长率\n\nFROM APP_CREDIT_REPORT_INFO i\nINNER JOIN APP_GUARANTOR_INFO g\n    ON i.ZXREPORTNO IN (g.ZXREPORTNOZX, g.zxReportNoSX)\nWHERE g.reportno = :reportNo\n  AND g.customername = :entName\n  AND g.guarantorname = :guarantorName\n  AND i.reportno = :reportNo\n  AND i.customername = :entName","paramData":[{"id":"2a9152b1-8542-a0db-0c17-d11b59c4d460","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"bd138d27-b35d-1604-20e3-ac40f629e622","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null},{"id":"63fa1a6a-7dec-c102-848f-8cd76318565c","name":"guarantorName","desc":"","type":"1","isSync":"Y","defaultValue":"''泰州公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin','','2026-09-04 19:17:21','admin','','2026-09-04 19:20:55',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2095329761296400386',NULL,0,'','','','','',NULL),('2097286270184075265','SHAREHOLDERVS','信贷股东与工商股东一致性对比','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2097203093293772801',NULL,'Public',NULL,'Auto','信贷股东信息','Public','1.0','3',NULL,NULL,NULL,'APP_XD_SHAREHOLDER_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_XD_SHAREHOLDER_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    COALESCE(x.CUSTOMERID, g.CUSTOMERID) AS 客户编号,\n    COALESCE(x.CUSTOMERNAME, g.CUSTOMERNAME) AS 客户名称,\n    COALESCE(x.NAME, g.NAME) AS 股东名称,\n    x.NAME AS 信贷股东名称,\n    g.NAME AS 工商股东名称,\n    CASE\n        WHEN x.NAME IS NULL THEN ''工商有、信贷无''\n        WHEN g.NAME IS NULL THEN ''信贷有、工商无''\n    END AS 对比结果\nFROM APP_XD_SHAREHOLDER_INFO x\nFULL OUTER JOIN APP_SHAREHOLDER_INFO g\n    ON x.CUSTOMERID = g.CUSTOMERID\n    AND x.NAME = g.NAME\n    AND g.reportno = :reportNo\n    AND g.customername = :entName\nWHERE COALESCE(x.REPORTNO, g.REPORTNO) = :reportNo\nAND COALESCE(x.CUSTOMERNAME, g.CUSTOMERNAME) = :entName\nAND (x.NAME IS NULL OR g.NAME IS NULL)\n  AND x.reportno = :reportNo\n  AND x.customername = :entName","paramData":[{"id":"aaa66566-dbcc-e75c-fb3a-daecfeaa2200","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"fb2fd6b5-b1f5-ffbc-e170-ed7d91551643","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-08 19:29:47','admin',NULL,'2026-09-08 19:32:54',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2097290837453975554','gongshangfaren','外部工商法人','CHAR','','','','Y','','label','','','2097290064745738241','','Public','','Auto','信贷法人与工商法人一致性对比','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-08 19:47:56','admin','','2026-09-08 19:47:56',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2097290064745738241',NULL,0,'','','','','',NULL),('2097298221127708674','SHAREHOLDERchange','授信后股东股权变更信息','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2097203093293772801',NULL,'Public',NULL,'Auto','信贷股东信息','Public','1.0','3',NULL,NULL,NULL,'APP_XD_SHAREHOLDER_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_XD_SHAREHOLDER_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    c.CUSTOMERID AS 客户编号,\n    c.CUSTOMERNAME AS 客户名称,\n    c.CREDITDATE AS 授信日期,\n    s.ICSHAREHOLDERNAME AS 股东名称,\n    s.icStockNum AS 持股数,\n    s.icAmount AS 投资金额,\n    s.CHANGETIME AS 变更时间,\n    s.PERCENTBEFORE AS 变更前持股比例,\n    s.PERCENTAFTER AS 变更后持股比例,\n    g.IS_STATE_OWNED AS 是否国有,\n    CASE\n        WHEN s.PERCENTBEFORE < 20 AND s.PERCENTAFTER >= 20\n            THEN ''新增''\n        WHEN s.PERCENTBEFORE >= 20 AND s.PERCENTAFTER < 20\n            THEN ''退出''\n        WHEN s.PERCENTBEFORE >= 20 AND s.PERCENTAFTER >= 20\n             AND s.PERCENTAFTER > s.PERCENTBEFORE\n            THEN ''上升''\n        WHEN s.PERCENTBEFORE >= 20 AND s.PERCENTAFTER >= 20\n             AND s.PERCENTAFTER < s.PERCENTBEFORE\n            THEN ''下降''\n        ELSE ''其他''\n    END AS 变更类型\nFROM APP_CREDIT_USE_INFO c\nINNER JOIN APP_IC_SHAREHOLDER_INFO s\n    ON c.CUSTOMERID = s.CUSTOMERID\n    AND s.reportno = :reportNo\n    AND s.customername = :entName\nLEFT JOIN APP_SHAREHOLDER_INFO g\n    ON s.CUSTOMERID = g.CUSTOMERID\n    AND s.ICSHAREHOLDERNAME = g.NAME\n    AND g.reportno = :reportNo\n    AND g.customername = :entName\nWHERE c.REPORTNO = :reportNo\nAND c.CUSTOMERNAME = :entName\nAND s.CHANGETIME > c.CREDITDATE\nAND (\n    s.PERCENTBEFORE >= 20\n    OR s.PERCENTAFTER >= 20\n)\nAND s.PERCENTBEFORE <> s.PERCENTAFTER","paramData":[{"id":"aaa66566-dbcc-e75c-fb3a-daecfeaa2200","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"fb2fd6b5-b1f5-ffbc-e170-ed7d91551643","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-08 20:17:16','admin',NULL,'2026-09-08 20:47:58',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('202609081425172','APP_XD_SHAREHOLDER_INFO','信贷股东信息','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2097203093293772801',NULL,'Public',NULL,'Auto','信贷股东信息','Public','1.0','3',NULL,NULL,NULL,'APP_XD_SHAREHOLDER_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_XD_SHAREHOLDER_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n \n\n    i.NAME AS 股东名称,\n    i.INVESTMENTPROP AS 持股比例,\n    i.CURRENCYTYPE AS 币种,\n    i.OUGHTSUM AS 投资金额,\n    i.INVESTMENTSUM AS 实缴金额,\n    i.INVESTDATE AS 投资时间\nFROM APP_XD_SHAREHOLDER_INFO i\nWHERE i.reportNo = :reportNo\nAND i.customername = :entName","paramData":[{"id":"aaa66566-dbcc-e75c-fb3a-daecfeaa2200","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"fb2fd6b5-b1f5-ffbc-e170-ed7d91551643","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-08 14:25:17','admin',NULL,'2026-09-08 15:53:36',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2026091114242427','PROPERTYINCOME','当年物业收入（万元）','CHAR',NULL,NULL,'Y','N',NULL,'label',NULL,NULL,'2026091114242417',NULL,'Public',NULL,'Auto','结算资产情况','Public','1.0','3',NULL,NULL,NULL,'PROPERTYINCOME','18,2','numeric',NULL,'是','当年物业收入（万元，接口待确认）','APP_SETTLE_ASSET_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-11 14:24:24','admin',NULL,'2026-09-11 14:24:24',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','',NULL,NULL),('2026091114242428','PROPERTYINCOMEYOY','当年物业收入累计较上年同期（万元）','CHAR',NULL,NULL,'Y','N',NULL,'label',NULL,NULL,'2026091114242417',NULL,'Public',NULL,'Auto','结算资产情况','Public','1.0','3',NULL,NULL,NULL,'PROPERTYINCOMEYOY','18,2','numeric',NULL,'是','当年物业收入累计较上年同期（万元，接口待确认）','APP_SETTLE_ASSET_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-11 14:24:24','admin',NULL,'2026-09-11 14:24:24',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','',NULL,NULL),('2026091114242429','PROPERTYINCOMESUPERVISED','当年监管账户物业收入（万元）','CHAR',NULL,NULL,'Y','N',NULL,'label',NULL,NULL,'2026091114242417',NULL,'Public',NULL,'Auto','结算资产情况','Public','1.0','3',NULL,NULL,NULL,'PROPERTYINCOMESUPERVISED','18,2','numeric',NULL,'是','当年监管账户物业收入（万元，接口待确认）','APP_SETTLE_ASSET_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-11 14:24:24','admin',NULL,'2026-09-11 14:24:24',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','',NULL,NULL),('2026091114242430','ELECTRICFEEINCOME','当年电费收入（万元）','CHAR',NULL,NULL,'Y','N',NULL,'label',NULL,NULL,'2026091114242417',NULL,'Public',NULL,'Auto','结算资产情况','Public','1.0','3',NULL,NULL,NULL,'ELECTRICFEEINCOME','18,2','numeric',NULL,'是','当年电费收入（万元，接口待确认）','APP_SETTLE_ASSET_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-11 14:24:24','admin',NULL,'2026-09-11 14:24:24',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','',NULL,NULL),('2026091114242431','ELECTRICFEEYOY','当年电费收入累计较上年同期（万元）','CHAR',NULL,NULL,'Y','N',NULL,'label',NULL,NULL,'2026091114242417',NULL,'Public',NULL,'Auto','结算资产情况','Public','1.0','3',NULL,NULL,NULL,'ELECTRICFEEYOY','18,2','numeric',NULL,'是','当年电费收入累计较上年同期（万元，接口待确认）','APP_SETTLE_ASSET_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-11 14:24:24','admin',NULL,'2026-09-11 14:24:24',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','',NULL,NULL),('2097289009907642370','SHAREHOLDERVSyesno','信贷股东与工商股东是否一致（是/否）','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2097203093293772801',NULL,'Public',NULL,'Auto','信贷股东信息','Public','1.0','3',NULL,NULL,NULL,'APP_XD_SHAREHOLDER_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_XD_SHAREHOLDER_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    CASE\n        WHEN COUNT(CASE WHEN x.NAME IS NULL OR g.NAME IS NULL THEN 1 END) > 0 THEN ''否''\n        ELSE ''是''\n    END AS 股东是否一致\nFROM APP_XD_SHAREHOLDER_INFO x\nFULL OUTER JOIN APP_SHAREHOLDER_INFO g\n    ON x.CUSTOMERID = g.CUSTOMERID\n    AND x.NAME = g.NAME\n    AND g.reportno = :reportNo\n    AND g.customername = :entName\nWHERE COALESCE(x.REPORTNO, g.REPORTNO) = :reportNo\nAND COALESCE(x.CUSTOMERNAME, g.CUSTOMERNAME) = :entName\n  AND x.reportno = :reportNo\n  AND x.customername = :entName","paramData":[{"id":"aaa66566-dbcc-e75c-fb3a-daecfeaa2200","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"fb2fd6b5-b1f5-ffbc-e170-ed7d91551643","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-08 19:40:40','admin',NULL,'2026-09-08 19:41:23',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2097290064745738241','farenyizhxing','信贷法人与工商法人一致性对比','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2094355937138651137',NULL,'Public',NULL,'Auto','信贷股东信息','Public','1.0','3',NULL,NULL,NULL,'APP_XD_SHAREHOLDER_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_XD_SHAREHOLDER_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    c.LEGALPERSON AS 信贷系统法人,\n    i.ICLEGALPERSON AS 外部工商法人,\n    CASE\n        WHEN c.LEGALPERSON = i.ICLEGALPERSON THEN ''是''\n        ELSE ''否''\n    END AS 是否一致\nFROM APP_CUSTOMER_INFO c\nLEFT JOIN APP_IC_INFO i\n    ON c.REPORTNO = i.REPORTNO\n    AND c.CUSTOMERID = i.CUSTOMERID\n    AND c.CUSTOMERNAME = i.CUSTOMERNAME\n    AND i.reportno = :reportNo\n    AND i.customername = :entName\nWHERE c.REPORTNO = :reportNo\nAND c.CUSTOMERNAME = :entName","paramData":[{"id":"aaa66566-dbcc-e75c-fb3a-daecfeaa2200","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"fb2fd6b5-b1f5-ffbc-e170-ed7d91551643","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-08 19:44:51','admin',NULL,'2026-09-08 19:45:43',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2097290950213644289','farenyizhihu','是否一致','CHAR','','','','Y','','label','','','2097290950213644289','','Public','','Auto','是否一致','Public','','','',NULL,'','','','','','','','','',NULL,'','',NULL,NULL,'admin','','2026-09-08 19:48:22','admin','','2026-09-08 19:48:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2094355937138651137',NULL,0,'','','','','',NULL),('2097301442667753473','SHAREHOLDERischange','授信后股东股权发生变更（是/否）','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2097203093293772801',NULL,'Public',NULL,'Auto','信贷股东信息','Public','1.0','3',NULL,NULL,NULL,'APP_XD_SHAREHOLDER_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_XD_SHAREHOLDER_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    CASE\n        WHEN COUNT(*) > 0 THEN ''是''\n        ELSE ''否''\n    END AS 是否存在重要股东变更\nFROM APP_CREDIT_USE_INFO c\nINNER JOIN APP_IC_SHAREHOLDER_INFO s\n    ON c.CUSTOMERID = s.CUSTOMERID\n    AND s.reportno = :reportNo\n    AND s.customername = :entName\nLEFT JOIN APP_SHAREHOLDER_INFO g\n    ON s.CUSTOMERID = g.CUSTOMERID\n    AND s.ICSHAREHOLDERNAME = g.NAME\n    AND g.reportno = :reportNo\n    AND g.customername = :entName\nWHERE c.REPORTNO = :reportNo\nAND c.CUSTOMERNAME = :entName\nAND s.CHANGETIME > c.CREDITDATE\nAND (\n    s.PERCENTBEFORE >= 20\n    OR s.PERCENTAFTER >= 20\n)\nAND s.PERCENTBEFORE <> s.PERCENTAFTER","paramData":[{"id":"aaa66566-dbcc-e75c-fb3a-daecfeaa2200","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"fb2fd6b5-b1f5-ffbc-e170-ed7d91551643","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-08 20:30:04','admin',NULL,'2026-09-08 20:32:24',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2097302136292388865','hoischange','是否存在重要股东变更','CHAR','','','','Y','','label','','','2097301442667753473','','Public','','Auto','授信后股东股权发生变更（是/否）','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-08 20:32:49','admin','','2026-09-08 20:32:49',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2097301442667753473',NULL,0,'','','','','',NULL),('2097303075615158273','cyiyangbu','股东是否一致','CHAR','','','','Y','','label','','','2097289009907642370','','Public','','Auto','信贷股东与工商股东是否一致（是/否）','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-08 20:36:33','admin','','2026-09-08 20:36:33',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2097289009907642370',NULL,0,'','','','','',NULL),('2097495303264415746','jkrjmgq','借款人是否假冒国企','CHAR','','','','Y','','label','','','2097494825562550273','','Public','','Auto','借款人及股东假冒国企','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-09 09:20:24','admin','','2026-09-09 09:20:24',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2097494825562550273',NULL,0,'','','','','',NULL),('2097495720996122625','jmgqgdxm','假冒国企股东名称','CHAR','','','','Y','','label','','','2097494825562550273','','Public','','Auto','借款人及股东假冒国企','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-09 09:22:04','admin','','2026-09-09 09:22:04',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2097494825562550273',NULL,0,'','','','','',NULL),('2097602428372267009','jjzhcptj','未结清借据组合产品统计','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2095502869399670786',NULL,'Public',NULL,'Auto','授信用信概况','Public','1.0','3',NULL,NULL,NULL,'APP_CREDIT_USE_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_CREDIT_USE_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    i.productBelongName AS 组合产品名称,\n    SUM(i.BALANCE) AS 借据余额\nFROM APP_LOAN_RECEIPT_INFO i\nWHERE i.REPORTNO = :reportNo\nAND i.CUSTOMERNAME = :entName\nAND i.LOANSTATUS NOT IN (''正常结清'', ''提前结清'', ''逾期结清'', ''理赔结清'')\nGROUP BY i.productBelongName","paramData":[{"id":"9cc31f8b-c0ce-4fbd-bab0-40613d884008","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"cfe523ee-9c4e-4fe4-165e-89fc654715dd","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-09 16:26:05','admin',NULL,'2026-09-09 17:12:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2026091114242423','DEBITSAMENAMETRANSFERRATIO','借方同名划转金额占比（%）','CHAR',NULL,NULL,'Y','N',NULL,'label',NULL,NULL,'2026091114242417',NULL,'Public',NULL,'Auto','结算资产情况','Public','1.0','3',NULL,NULL,NULL,'DEBITSAMENAMETRANSFERRATIO','5,2','numeric',NULL,'是','借方同名划转金额占比（%）','APP_SETTLE_ASSET_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-11 14:24:24','admin',NULL,'2026-09-11 14:24:24',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','',NULL,NULL),('2097609822494011393','jjwjqzqcztj','未结清借据展期重组等统计','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2095502869399670786',NULL,'Public',NULL,'Auto','授信用信概况','Public','1.0','3',NULL,NULL,NULL,'APP_CREDIT_USE_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_CREDIT_USE_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    COUNT(CASE\n        WHEN i.LOANCHANGERPTCOUNTS > 0 THEN 1\n    END) AS 还款方式变更借据数量,\n    COALESCE(SUM(CASE\n        WHEN i.LOANCHANGERPTCOUNTS > 0 THEN i.BALANCE\n        ELSE 0\n    END), 0) AS 还款方式变更借据余额,\n\n    COUNT(CASE\n        WHEN i.ISEXTEND = ''是'' THEN 1\n    END) AS 展期借据数量,\n    COALESCE(SUM(CASE\n        WHEN i.ISEXTEND = ''是'' THEN i.BALANCE\n        ELSE 0\n    END), 0) AS 展期借据余额,\n\n    COUNT(CASE\n        WHEN i.ISRESTRUCTED = ''是'' THEN 1\n    END) AS 重组借据数量,\n    COALESCE(SUM(CASE\n        WHEN i.ISRESTRUCTED = ''是'' THEN i.BALANCE\n        ELSE 0\n    END), 0) AS 重组借据余额,\n\n    COUNT(CASE\n        WHEN i.OCCURTYPE = ''借新还旧'' THEN 1\n    END) AS 借新还旧借据数量,\n    COALESCE(SUM(CASE\n        WHEN i.OCCURTYPE = ''借新还旧'' THEN i.BALANCE\n        ELSE 0\n    END), 0) AS 借新还旧借据余额\n\nFROM APP_LOAN_RECEIPT_INFO i\nWHERE i.REPORTNO = :reportNo\nAND i.CUSTOMERNAME = :entName\nAND i.LOANSTATUS NOT IN (''正常结清'', ''提前结清'', ''逾期结清'', ''理赔结清'')","paramData":[{"id":"9cc31f8b-c0ce-4fbd-bab0-40613d884008","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"cfe523ee-9c4e-4fe4-165e-89fc654715dd","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-09 16:55:28','admin',NULL,'2026-09-09 16:56:26',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2026091114242424','CREDITSAMENAMETRANSFERRATIO','贷方同名划转金额占比（%）','CHAR',NULL,NULL,'Y','N',NULL,'label',NULL,NULL,'2026091114242417',NULL,'Public',NULL,'Auto','结算资产情况','Public','1.0','3',NULL,NULL,NULL,'CREDITSAMENAMETRANSFERRATIO','5,2','numeric',NULL,'是','贷方同名划转金额占比（%）','APP_SETTLE_ASSET_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-11 14:24:24','admin',NULL,'2026-09-11 14:24:24',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','',NULL,NULL),('2026091114242425','YEARAVGDEPOSIT','年日均存款（万元）','CHAR',NULL,NULL,'Y','N',NULL,'label',NULL,NULL,'2026091114242417',NULL,'Public',NULL,'Auto','结算资产情况','Public','1.0','3',NULL,NULL,NULL,'YEARAVGDEPOSIT','18,2','numeric',NULL,'是','年日均存款（万元）','APP_SETTLE_ASSET_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-11 14:24:24','admin',NULL,'2026-09-11 14:24:24',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','',NULL,NULL),('2026091114242426','LASTYEARAVGDEPOSIT','上年年日均存款（万元）','CHAR',NULL,NULL,'Y','N',NULL,'label',NULL,NULL,'2026091114242417',NULL,'Public',NULL,'Auto','结算资产情况','Public','1.0','3',NULL,NULL,NULL,'LASTYEARAVGDEPOSIT','18,2','numeric',NULL,'是','上年年日均存款（万元）','APP_SETTLE_ASSET_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-11 14:24:24','admin',NULL,'2026-09-11 14:24:24',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','',NULL,NULL),('2097494825562550273','jkejgdjmgq','借款人及股东假冒国企','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2097203093293772801',NULL,'Public',NULL,'Auto','信贷股东信息','Public','1.0','3',NULL,NULL,NULL,'APP_XD_SHAREHOLDER_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_XD_SHAREHOLDER_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    i.CUSTOMERID AS 客户编号,\n    i.CUSTOMERNAME AS 客户名称,\n\n    -- 1、借款人是否假冒国企\n    CASE\n        WHEN i.ISFAKESTATEOWNED = ''是'' THEN ''是''\n        ELSE ''否''\n    END AS 借款人是否假冒国企,\n\n    -- 2、是否有股东假冒国企\n    CASE\n        WHEN EXISTS (\n            SELECT 1\n            FROM APP_SHAREHOLDER_INFO s\n            WHERE s.CUSTOMERID = i.CUSTOMERID\n              AND s.IS_FAKE_STATE_OWNED = ''是''\n  AND s.reportno = :reportNo\n  AND s.customername = :entName\n        )\n        THEN ''是''\n        ELSE ''否''\n    END AS 是否有股东假冒国企,\n\n    -- 3、假冒国企的股东名称\n    (\n        SELECT LISTAGG(s.NAME, ''、'')\n               WITHIN GROUP (ORDER BY s.NAME)\n        FROM APP_SHAREHOLDER_INFO s\n        WHERE s.CUSTOMERID = i.CUSTOMERID\n          AND s.IS_FAKE_STATE_OWNED = ''是''\n  AND s.reportno = :reportNo\n  AND s.customername = :entName\n    ) AS 假冒国企股东名称\n\nFROM APP_IC_INFO i\nWHERE i.REPORTNO = :reportNo\nAND i.CUSTOMERNAME = :entName","paramData":[{"id":"aaa66566-dbcc-e75c-fb3a-daecfeaa2200","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"fb2fd6b5-b1f5-ffbc-e170-ed7d91551643","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-09 09:18:30','admin',NULL,'2026-09-09 09:21:26',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2097601822563774465','jjjccptj','未结清借据基础产品统计','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2095502869399670786',NULL,'Public',NULL,'Auto','授信用信概况','Public','1.0','3',NULL,NULL,NULL,'APP_CREDIT_USE_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_CREDIT_USE_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    i.PRODUCTNAME AS 基础产品名称,\n    SUM(i.BALANCE) AS 借据余额\nFROM APP_LOAN_RECEIPT_INFO i\nWHERE i.REPORTNO = :reportNo\nAND i.CUSTOMERNAME = :entName\nAND i.LOANSTATUS NOT IN (''正常结清'', ''提前结清'', ''逾期结清'', ''理赔结清'')\nGROUP BY i.PRODUCTNAME","paramData":[{"id":"9cc31f8b-c0ce-4fbd-bab0-40613d884008","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"cfe523ee-9c4e-4fe4-165e-89fc654715dd","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-09 16:23:40','admin',NULL,'2026-09-09 17:12:13',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2097618591156285442','fdckfcp','房地产开发产品下次还款','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2095502869399670786',NULL,'Public',NULL,'Auto','授信用信概况','Public','1.0','3',NULL,NULL,NULL,'APP_CREDIT_USE_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_CREDIT_USE_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    i.NEXTPAYDATE AS 下一还款日期,\n    i.PAYPRINCIPALAMT AS 应还本金,\n    i.REPAYMENTPERIOD AS 还款周期,\n    i.BUSINESSRATE AS 执行利率\nFROM APP_LOAN_RECEIPT_INFO i\nWHERE i.REPORTNO = :reportNo\nAND i.CUSTOMERNAME = :entName\nAND i.realEstateDevLoan = ''是''\nAND i.LOANSTATUS NOT IN (''正常结清'', ''提前结清'', ''逾期结清'', ''理赔结清'')\nORDER BY i.NEXTPAYDATE ASC\nLIMIT 1","paramData":[{"id":"9cc31f8b-c0ce-4fbd-bab0-40613d884008","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"cfe523ee-9c4e-4fe4-165e-89fc654715dd","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-09 17:30:18','admin',NULL,'2026-09-09 17:31:23',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2097654262000529409','xudkbiaoge','项目贷款表格数据','