况','Public','1.0','3',NULL,NULL,NULL,'CUSTOMERID','64','character varying',NULL,'是','客户编号','APP_SETTLE_ASSET_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-11 14:24:24','admin',NULL,'2026-09-11 14:24:24',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','',NULL,NULL),('2098076921578401793','dfgzycpd','判断代发工资是否异常','LIST','','','','Y','','label','','','2098246577538740225','','Public','','Auto','代发业务情况','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    CASE\n        WHEN COUNT(*) >= 3\n         AND COUNT(CASE WHEN rn <= 3 AND countMom < 0 THEN 1 END) = 3\n        THEN ''是''\n        ELSE ''否''\n    END AS 代发人数连续三期逐步减少,\n\n    CASE\n        WHEN COUNT(*) >= 3\n         AND COUNT(CASE WHEN rn <= 3 AND amountMom < 0 THEN 1 END) = 3\n        THEN ''是''\n        ELSE ''否''\n    END AS 代发金额连续三期逐步减少,\n\n    CASE\n        WHEN COUNT(*) >= 3\n         AND COUNT(CASE WHEN rn <= 3 AND countYoy < 0 THEN 1 END) = 3\n        THEN ''是''\n        ELSE ''否''\n    END AS 连续三期代发人数同比下降,\n\n    CASE\n        WHEN COUNT(*) >= 3\n         AND COUNT(CASE WHEN rn <= 3 AND amountYoy < 0 THEN 1 END) = 3\n        THEN ''是''\n        ELSE ''否''\n    END AS 连续三期代发金额同比下降\nFROM (\n    SELECT\n        i.STATMONTH AS statMonth,\n        i.COUNTMOM AS countMom,\n        i.AMOUNTMOM AS amountMom,\n        i.COUNTYOY AS countYoy,\n        i.AMOUNTYOY AS amountYoy,\n        ROW_NUMBER() OVER (\n            ORDER BY i.STATMONTH DESC\n        ) AS rn\n    FROM APP_PAYROLL_STAT_INFO i\n    WHERE i.REPORTNO = :reportNo\n    AND i.CUSTOMERNAME = :entName\n) t\nWHERE rn <= 3","paramData":[{"id":"38a09880-39f7-bfed-a329-5f81d64fd4f6","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"4333b0d6-3a4d-bea5-20e3-5923ba7e1c1a","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin','','2026-09-10 23:51:33','admin','','2026-09-11 11:07:05',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2094972118262427650',NULL,0,'','','','','',NULL),('2026091114242421','CUSTOMERNAME','客户名称','CHAR',NULL,NULL,'Y','N',NULL,'label',NULL,NULL,'2026091114242417',NULL,'Public',NULL,'Auto','结算资产情况','Public','1.0','3',NULL,NULL,NULL,'CUSTOMERNAME','128','character varying',NULL,'是','客户名称','APP_SETTLE_ASSET_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-11 14:24:24','admin',NULL,'2026-09-11 14:24:24',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','',NULL,NULL),('2026091114242422','FROZENAMOUNT','冻结金额（万元）','CHAR',NULL,NULL,'Y','N',NULL,'label',NULL,NULL,'2026091114242417',NULL,'Public',NULL,'Auto','结算资产情况','Public','1.0','3',NULL,NULL,NULL,'FROZENAMOUNT','18,2','numeric',NULL,'是','冻结金额（万元）','APP_SETTLE_ASSET_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-11 14:24:24','admin',NULL,'2026-09-11 14:24:24',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','',NULL,NULL),('2026091114242432','ELECTRICFEESUPERVISED','当年监管账户当年电费收入（万元）','CHAR',NULL,NULL,'Y','N',NULL,'label',NULL,NULL,'2026091114242417',NULL,'Public',NULL,'Auto','结算资产情况','Public','1.0','3',NULL,NULL,NULL,'ELECTRICFEESUPERVISED','18,2','numeric',NULL,'是','当年监管账户当年电费收入（万元，接口待确认）','APP_SETTLE_ASSET_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-11 14:24:24','admin',NULL,'2026-09-11 14:24:24',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','',NULL,NULL),('2026091114242433','KEYWORDCOUNTERPARTYCREDITAMOUNT','当年交易对手中出现小额贷款、担保等关键字的公司贷方发生额（万元）','CHAR',NULL,NULL,'Y','N',NULL,'label',NULL,NULL,'2026091114242417',NULL,'Public',NULL,'Auto','结算资产情况','Public','1.0','3',NULL,NULL,NULL,'KEYWORDCOUNTERPARTYCREDITAMOUNT','18,2','numeric',NULL,'是','当年交易对手中出现小额贷款、担保等关键字的公司贷方发生额（万元）','APP_SETTLE_ASSET_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-11 14:24:24','admin',NULL,'2026-09-11 14:24:24',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','',NULL,NULL),('2026091114242434','KEYWORDREMARKCREDITAMOUNT','当年备注中有担保、借款、投资关键字贷方发生额（万元）','CHAR',NULL,NULL,'Y','N',NULL,'label',NULL,NULL,'2026091114242417',NULL,'Public',NULL,'Auto','结算资产情况','Public','1.0','3',NULL,NULL,NULL,'KEYWORDREMARKCREDITAMOUNT','18,2','numeric',NULL,'是','当年备注中有担保、借款、投资关键字贷方发生额（万元）','APP_SETTLE_ASSET_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-11 14:24:24','admin',NULL,'2026-09-11 14:24:24',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','',NULL,NULL),('2026091114242435','INPUTTIME','入库时间','CHAR',NULL,NULL,'Y','N',NULL,'label',NULL,NULL,'2026091114242417',NULL,'Public',NULL,'Auto','结算资产情况','Public','1.0','3',NULL,NULL,NULL,'INPUTTIME','','timestamp without time zone',NULL,'是','入库时间','APP_SETTLE_ASSET_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-11 14:24:24','admin',NULL,'2026-09-11 14:24:24',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','',NULL,NULL),('2026091114242417','APP_SETTLE_ASSET_INFO','结算资产情况','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2098246641996804097',NULL,'Public',NULL,'Auto','结算资产情况','Public','1.0','3',NULL,NULL,NULL,'APP_SETTLE_ASSET_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_SETTLE_ASSET_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    i.ID,\n    i.REPORTNO,\n    i.CUSTOMERID,\n    i.CUSTOMERNAME,\n    i.FROZENAMOUNT,\n    i.DEBITSAMENAMETRANSFERRATIO,\n    i.CREDITSAMENAMETRANSFERRATIO,\n    i.YEARAVGDEPOSIT,\n    i.LASTYEARAVGDEPOSIT,\n    i.PROPERTYINCOME,\n    i.PROPERTYINCOMEYOY,\n    i.PROPERTYINCOMESUPERVISED,\n    i.ELECTRICFEEINCOME,\n    i.ELECTRICFEEYOY,\n    i.ELECTRICFEESUPERVISED,\n    i.KEYWORDCOUNTERPARTYCREDITAMOUNT,\n    i.KEYWORDREMARKCREDITAMOUNT,\n    i.INPUTTIME\nFROM APP_SETTLE_ASSET_INFO i\nWHERE i.REPORTNO = :reportNo\nAND i.CUSTOMERNAME = :entName","paramData":[{"id":"ee7c14df-4130-bf5a-1564-b0afa52af762","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"e6710754-a470-f9ff-2705-da94adc715a7","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-11 14:24:24','admin',NULL,'2026-09-11 14:28:06',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2098297608888922113','jszhxx','结算账户信息','LIST','','','','Y','','label','','','2098246641996804097','','Public','','Auto','批复管理要求','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    i.ID AS ID,\n    i.REPORTNO AS 报告编号,\n    i.CUSTOMERID AS 客户编号,\n    i.CUSTOMERNAME AS 客户名称,\n    i.ACCOUNTNO AS 账号,\n    i.ACCOUNTSTATUS AS 账户状态,\n    i.ACCOUNTBALANCE AS 账户余额（万元）,\n    i.SUPERVISEFLAG AS 监管标识,\n    i.INPUTTIME AS 入库时间\nFROM APP_SETTLE_ACCOUNT_INFO i\nWHERE i.REPORTNO = :reportNo\nAND i.CUSTOMERNAME = :entName","paramData":[{"id":"38a09880-39f7-bfed-a329-5f81d64fd4f6","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"4333b0d6-3a4d-bea5-20e3-5923ba7e1c1a","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin','','2026-09-11 14:28:29','admin','','2026-09-11 14:29:53',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2094972118262427650',NULL,0,'','','','','',NULL),('2098255255243337730','jsyjypp','前五大上下游客户在借贷方前十大结算交易对手中的匹配率','LIST','','','','Y','','label','','','2098246497964404737','','Public','','Auto','结算交易对手情况','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    ROUND(\n        COUNT(DISTINCT CASE\n            WHEN u.SUPPLIERTYPENAME = ''前五大上游''\n             AND u.SUPPLIER IS NOT NULL\n             AND EXISTS (\n                 SELECT 1\n                 FROM APP_SETTLE_COUNTERPARTY_INFO s\n                 WHERE s.REPORTNO = u.REPORTNO\n                   AND s.CUSTOMERID = u.CUSTOMERID\n                   AND s.CUSTOMERNAME = u.CUSTOMERNAME\n                   AND s.DIRECTION = ''借方''\n                   AND s.RANKNO IN (\n                       ''TOP1'', ''TOP2'', ''TOP3'', ''TOP4'', ''TOP5'',\n                       ''TOP6'', ''TOP7'', ''TOP8'', ''TOP9'', ''TOP10''\n                   )\n                   AND s.COUNTERPARTYNAME = u.SUPPLIER\n  AND s.reportno = :reportNo\n  AND s.customername = :entName\n             )\n            THEN u.SUPPLIER\n        END) * 100.0\n        / NULLIF(\n            COUNT(DISTINCT CASE\n                WHEN u.SUPPLIERTYPENAME = ''前五大上游''\n                THEN u.SUPPLIER\n            END),\n            0\n        ),\n        2\n    ) AS 前五大上游与借方前十大匹配率,\n\n    ROUND(\n        COUNT(DISTINCT CASE\n            WHEN u.SUPPLIERTYPENAME = ''前五大下游''\n             AND u.SUPPLIER IS NOT NULL\n             AND EXISTS (\n                 SELECT 1\n                 FROM APP_SETTLE_COUNTERPARTY_INFO s\n                 WHERE s.REPORTNO = u.REPORTNO\n                   AND s.CUSTOMERID = u.CUSTOMERID\n                   AND s.CUSTOMERNAME = u.CUSTOMERNAME\n                   AND s.DIRECTION = ''贷方''\n                   AND s.RANKNO IN (\n                       ''TOP1'', ''TOP2'', ''TOP3'', ''TOP4'', ''TOP5'',\n                       ''TOP6'', ''TOP7'', ''TOP8'', ''TOP9'', ''TOP10''\n                   )\n                   AND s.COUNTERPARTYNAME = u.SUPPLIER\n  AND s.reportno = :reportNo\n  AND s.customername = :entName\n             )\n            THEN u.SUPPLIER\n        END) * 100.0\n        / NULLIF(\n            COUNT(DISTINCT CASE\n                WHEN u.SUPPLIERTYPENAME = ''前五大下游''\n                THEN u.SUPPLIER\n            END),\n            0\n        ),\n        2\n    ) AS 前五大下游与贷方前十大匹配率\nFROM APP_TOP_FIVE_UPDOWN_INFO u\nWHERE u.REPORTNO = :reportNo\nAND u.CUSTOMERNAME = :entName\nAND u.SUPPLIERTYPENAME IN (''前五大上游'', ''前五大下游'')","paramData":[{"id":"38a09880-39f7-bfed-a329-5f81d64fd4f6","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"4333b0d6-3a4d-bea5-20e3-5923ba7e1c1a","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin','','2026-09-11 11:40:11','admin','','2026-09-11 14:52:01',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2094972118262427650',NULL,0,'','','','','',NULL),('2098323678967115777','ssgssfyzdyq','上市股东是否有重大舆情','CHAR','','','','Y','','label','','','2098322971241230338','','Public','','Auto','上市企业及上市股东舆情判断指标','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-11 16:12:04','admin','','2026-09-11 16:12:04',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2098322971241230338',NULL,0,'','','','','',NULL),('2098323771304718337','ssgdcgblhj','上市股东持股比例合计','CHAR','','','','Y','','label','','','2098322971241230338','','Public','','Auto','上市企业及上市股东舆情判断指标','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-11 16:12:26','admin','','2026-09-11 16:12:37',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2098316746944425985',NULL,0,'','','','','',NULL),('2098322971241230338','ssqyjgzzdyqpdzb','上市企业及上市股东舆情判断指标','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2098316746944425985',NULL,'Public',NULL,'Auto','信贷股东信息','Public','1.0','3',NULL,NULL,NULL,'APP_XD_SHAREHOLDER_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_XD_SHAREHOLDER_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    CASE\n        WHEN EXISTS (\n            SELECT 1\n            FROM APP_REPUTATION_EVENT_INFO r\n            WHERE r.REPORTNO = c.REPORTNO\n              AND r.CUSTOMERID = c.CUSTOMERID\n              AND r.CUSTOMERNAME = c.CUSTOMERNAME\n              AND r.SUBJECTTYPE = ''借款人''\n              AND r.SUBJECTNAME = c.CUSTOMERNAME\n              AND r.EVENTTYPE IN (\n                  ''证券市场违规问题'',\n                  ''企业股票戴帽'',\n                  ''企业有退市风险'',\n                  ''企业评级被下调'',\n                  ''企业高管无法履职'',\n                  ''财务造假''\n              )\n  AND r.reportno = :reportNo\n  AND r.customername = :entName\n        )\n        THEN ''是''\n        ELSE ''否''\n    END AS 借款人是否有重大舆情,\n\n    CASE\n        WHEN EXISTS (\n            SELECT 1\n            FROM APP_REPUTATION_EVENT_INFO r\n            INNER JOIN APP_SHAREHOLDER_INFO s\n                ON s.REPORTNO = r.REPORTNO\n                AND s.CUSTOMERID = r.CUSTOMERID\n                AND s.CUSTOMERNAME = r.CUSTOMERNAME\n                AND s.NAME = r.SUBJECTNAME\n    AND s.reportno = :reportNo\n    AND s.customername = :entName\n            WHERE r.REPORTNO = c.REPORTNO\n              AND r.CUSTOMERID = c.CUSTOMERID\n              AND r.CUSTOMERNAME = c.CUSTOMERNAME\n              AND r.SUBJECTTYPE = ''股东''\n              AND s.IS_QUOTED = ''是''\n              AND r.EVENTTYPE IN (\n                  ''证券市场违规问题'',\n                  ''企业股票戴帽'',\n                  ''企业有退市风险'',\n                  ''企业评级被下调'',\n                  ''企业高管无法履职'',\n                  ''财务造假''\n              )\n  AND r.reportno = :reportNo\n  AND r.customername = :entName\n        )\n        THEN ''是''\n        ELSE ''否''\n    END AS 上市股东是否有重大舆情,\n\n    COALESCE((\n        SELECT SUM(s.STOCK_PERCENT)\n        FROM APP_SHAREHOLDER_INFO s\n        WHERE s.REPORTNO = c.REPORTNO\n          AND s.CUSTOMERID = c.CUSTOMERID\n          AND s.CUSTOMERNAME = c.CUSTOMERNAME\n          AND s.IS_QUOTED = ''是''\n  AND s.reportno = :reportNo\n  AND s.customername = :entName\n    ), 0) AS 上市股东持股比例合计\n\nFROM APP_CUSTOMER_INFO c\nWHERE c.REPORTNO = :reportNo\nAND c.CUSTOMERNAME = :entName","paramData":[{"id":"aaa66566-dbcc-e75c-fb3a-daecfeaa2200","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"fb2fd6b5-b1f5-ffbc-e170-ed7d91551643","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-11 16:09:15','admin',NULL,'2026-09-11 16:10:27',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2098316981716398082','shqijgdyq','上市企业及上市股东舆情','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2098316746944425985',NULL,'Public',NULL,'Auto','信贷股东信息','Public','1.0','3',NULL,NULL,NULL,'APP_XD_SHAREHOLDER_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_XD_SHAREHOLDER_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    i.ID AS ID,\n    i.REPORTNO AS 报告编号,\n    i.CUSTOMERID AS 客户编号,\n    i.CUSTOMERNAME AS 客户名称,\n    i.SUBJECTTYPE AS 主体类型,\n    i.SUBJECTNAME AS 主体名称,\n    CASE\n        WHEN i.SUBJECTTYPE = ''借款人'' THEN c.ISLISTEDCOMPANY\n        WHEN i.SUBJECTTYPE = ''股东'' THEN s.IS_QUOTED\n    END AS 是否上市,\n    CASE\n        WHEN i.SUBJECTTYPE = ''股东'' THEN s.STOCK_PERCENT\n    END AS 持股比例,\n    i.EVENTTIME AS 舆情发生时间,\n    i.EVENTTYPE AS 舆情类型,\n    i.EVENTDESC AS 舆情事件描述,\n    i.INPUTTIME AS 入库时间\nFROM APP_REPUTATION_EVENT_INFO i\nLEFT JOIN APP_CUSTOMER_INFO c\n    ON c.REPORTNO = i.REPORTNO\n    AND c.CUSTOMERID = i.CUSTOMERID\n    AND c.CUSTOMERNAME = i.CUSTOMERNAME\n    AND i.SUBJECTTYPE = ''借款人''\n    AND i.SUBJECTNAME = c.CUSTOMERNAME\n    AND c.reportno = :reportNo\n    AND c.customername = :entName\nLEFT JOIN APP_SHAREHOLDER_INFO s\n    ON s.REPORTNO = i.REPORTNO\n    AND s.CUSTOMERID = i.CUSTOMERID\n    AND s.CUSTOMERNAME = i.CUSTOMERNAME\n    AND i.SUBJECTTYPE = ''股东''\n    AND i.SUBJECTNAME = s.NAME\n    AND s.reportno = :reportNo\n    AND s.customername = :entName\nWHERE i.REPORTNO = :reportNo\nAND i.CUSTOMERNAME = :entName\nAND i.EVENTTYPE IN (\n    ''证券市场违规问题'',\n    ''企业股票戴帽'',\n    ''企业有退市风险'',\n    ''企业评级被下调'',\n    ''企业高管无法履职'',\n    ''财务造假''\n)\nAND (\n    (\n        i.SUBJECTTYPE = ''借款人''\n        AND c.ISLISTEDCOMPANY = ''是''\n    )\n    OR\n    (\n        i.SUBJECTTYPE = ''股东''\n        AND s.IS_QUOTED = ''是''\n    )\n)","paramData":[{"id":"aaa66566-dbcc-e75c-fb3a-daecfeaa2200","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"fb2fd6b5-b1f5-ffbc-e170-ed7d91551643","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-11 15:45:27','admin',NULL,'2026-09-11 16:06:01',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2098323484926029826','jkrsfyzdyq','借款人是否有重大舆情','CHAR','','','','Y','','label','','','2098322971241230338','','Public','','Auto','上市企业及上市股东舆情判断指标','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin',