,'CHAR',NULL,NULL,'Y','N',NULL,'label',NULL,NULL,'2099323827382136834',NULL,'Public',NULL,'Auto','财务科目-最新一期合并','Public','1.0','3',NULL,NULL,NULL,'ACCOUNTMONTH','32','character varying',NULL,'是','会计月','APP_FINANCE_INDICATOR_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-14 10:26:18','admin',NULL,'2026-09-14 10:26:18',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','',NULL,NULL),('2099322942107168770','SALESPROFITRATIO','销售利率','CHAR',NULL,NULL,'Y','N',NULL,'label',NULL,NULL,'2099322941880676353',NULL,'Public',NULL,'Auto','财务科目-最新一期合并','Public','1.0','3',NULL,NULL,NULL,'SALESPROFITRATIO','12,4','numeric',NULL,'是','销售利率（%）','APP_FINANCE_INDICATOR_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-14 10:22:47','admin',NULL,'2026-09-14 10:22:47',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','',NULL,NULL),('2099322942107168771','NETPROFITRATIO','净利率','CHAR',NULL,NULL,'Y','N',NULL,'label',NULL,NULL,'2099322941880676353',NULL,'Public',NULL,'Auto','财务科目-最新一期合并','Public','1.0','3',NULL,NULL,NULL,'NETPROFITRATIO','12,4','numeric',NULL,'是','净利率（%）','APP_FINANCE_INDICATOR_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-14 10:22:47','admin',NULL,'2026-09-14 10:22:47',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','',NULL,NULL),('2099321043698069505','APP_FINANCE_INDICATOR_INFO_zx_hb','财务科目-最新一期合并','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2099492891123527682',NULL,'Public',NULL,'Auto','财务科目','Public','1.0','3',NULL,NULL,NULL,'APP_FINANCE_INDICATOR_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_FINANCE_INDICATOR_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    i.ID AS ID,\n    i.REPORTNO AS 报告编号,\n    i.CUSTOMERID AS 客户编号,\n    i.CUSTOMERNAME AS 客户名称,\n    i.FINREPORTNO AS 财报编号,\n    i.ACCOUNTMONTH AS 会计月,\n    i.REPORTSCOPE AS 报表口径,\n    i.REPORTPERIOD AS 报表周期,\n    i.AUDITFLAG AS 是否审计,\n    i.CURRENCY AS 报表币种,\n    i.MONETARYUNIT AS 货币单位,\n    i.REPORTSTATUSNAME AS 报表状态中文,\n    i.REPORTSTATUS AS 报表状态码值,\n    i.INPUTTIME AS 入库时间,\n    i.REPORTTYPENO AS 报表类型,\n    i.REPORTTYPENAME AS 报表类型名称,\n    i.REVENUE AS 营业收入,\n    i.REVENUEYOY AS 营业收入同比,\n    i.NETPROFIT AS 净利润,\n    i.NETPROFITYOY AS 净利润同比,\n    i.PAIDINCAPITAL AS 实收资本,\n    i.TOTALEQUITY AS 所有者权益合计,\n    i.ACCOUNTSRECEIVABLE AS 应收账款,\n    i.ARCHANGEFROMYEARSTART AS 应收账款较年初变动,\n    i.ARCHANGEFROMYEARSTARTRATE AS 应收账款较年初增幅,\n    i.OTHERRECEIVABLE AS 其他应收款,\n    i.ORCHANGEFROMYEARSTART AS 其他应收款较年初变动,\n    i.ORCHANGEFROMYEARSTARTRATE AS 其他应收款较年初增幅,\n    i.ARORTOTALASSETRATIO AS 应收账款和其他应收款合计占总资产比例,\n    i.SHORTLOAN AS 短期借款,\n    i.SHORTLOANCHANGEFROMYEARSTART AS 短期借款较年初变动,\n    i.SHORTLOANCHANGEFROMYEARSTARTRATE AS 短期借款较年初增幅,\n    i.LONGLOAN AS 长期借款,\n    i.LONGLOANCHANGEFROMYEARSTART AS 长期借款较年初变动,\n    i.LONGLOANCHANGEFROMYEARSTARTRATE AS 长期借款较年初增幅,\n    i.LONGLOANDUEWITHIN1Y AS 一年内到期的长期借款,\n    i.SALESLOANRATIO AS 销贷比,\n    i.NOTESPAYABLE AS 应付票据,\n    i.NOTESPAYABLECHANGEFROMYEARSTART AS 应付票据较年初变动,\n    i.NOTESPAYABLECHANGEFROMYEARSTARTRATE AS 应付票据较年初增幅,\n    i.OTHERPAYABLE AS 其他应付款,\n    i.OTHERPAYABLECHANGEFROMYEARSTART AS 其他应付款较年初变动,\n    i.OTHERPAYABLECHANGEFROMYEARSTARTRATE AS 其他应付款较年初增幅,\n    i.SLTOTALLOANYOY AS 短期借款和长期借款合计同比,\n    i.ARYOY AS 应收账款同比,\n    i.ARTURNOVERDAYS AS 应收账款周转天数,\n    i.INVENTORYTURNOVERDAYS AS 存货周转天数,\n    i.INVENTORYYOY AS 存货同比,\n    i.ACCOUNTSPAYABLE AS 应付账款,\n    i.INVENTORY AS 存货,\n    i.DEBTRATIO AS 资产负债率,\n    i.SALESPROFITRATIO AS 销售利率,\n    i.NETPROFITRATIO AS 净利率\nFROM APP_FINANCE_INDICATOR_INFO i\nWHERE i.REPORTNO = :reportNo\n  AND i.CUSTOMERNAME = :entName\n  AND i.REPORTSCOPE = ''合并''\n  AND i.subjectType=''借款人''\n  AND i.ACCOUNTMONTH = (\n      SELECT MAX(i2.ACCOUNTMONTH)\n      FROM APP_FINANCE_INDICATOR_INFO i2\n      WHERE i2.REPORTNO = :reportNo\n        AND i2.CUSTOMERNAME = :entName\n  )\nlimit 1","paramData":[{"id":"54b10e26-eac0-d8dd-0c52-1154a40f3c5a","name":"reportN