3ee-9c4e-4fe4-165e-89fc654715dd","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-14 19:54:50','admin',NULL,'2026-09-14 19:59:06',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2099468248912244738','ghgdjk','归还股东借款金额','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2095502869399670786',NULL,'Public',NULL,'Auto','授信用信概况','Public','1.0','3',NULL,NULL,NULL,'APP_CREDIT_USE_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_CREDIT_USE_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    SUM(i.BUSINESSSUM) AS 归还股东借款金额\nFROM APP_LOAN_RECEIPT_INFO i\nWHERE i.REPORTNO = :reportNo\nAND i.CUSTOMERNAME = :entName\nAND i.LOANSTATUS NOT IN (''正常结清'', ''提前结清'', ''逾期结清'', ''理赔结清'')\nand i.purposeName like ''%归还股东借款%''","paramData":[{"id":"9cc31f8b-c0ce-4fbd-bab0-40613d884008","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"cfe523ee-9c4e-4fe4-165e-89fc654715dd","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-14 20:00:11','admin',NULL,'2026-09-15 14:30:17',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2099468249075822594','ghgdjk','归还股东借款金额','CHAR','','','','Y','','label','','','2099468248912244738','','Public','','Auto','非项目贷款借据余额','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-14 20:00:11','admin','','2026-09-14 20:04:57',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2099466901378838530',NULL,0,'','','','','',NULL),('2099473094558101506','APP_FINANCE_INDICATOR_INFO_sntq_bb','财务科目-上年同期本部','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2099492891123527682',NULL,'Public',NULL,'Auto','财务科目','Public','1.0','3',NULL,NULL,NULL,'APP_FINANCE_INDICATOR_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_FINANCE_INDICATOR_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    i.ID AS ID,\n    i.REPORTNO AS 报告编号,\n    i.CUSTOMERID AS 客户编号,\n    i.CUSTOMERNAME AS 客户名称,\n    i.FINREPORTNO AS 财报编号,\n    i.ACCOUNTMONTH AS 会计月,\n    i.REPORTSCOPE AS 报表口径,\n    i.REPORTPERIOD AS 报表周期,\n    i.AUDITFLAG AS 是否审计,\n    i.CURRENCY AS 报表币种,\n    i.MONETARYUNIT AS 货币单位,\n    i.REPORTSTATUSNAME AS 报表状态中文,\n    i.REPORTSTATUS AS 报表状态码值,\n    i.INPUTTIME AS 入库时间,\n    i.REPORTTYPENO AS 报表类型,\n    i.REPORTTYPENAME AS 报表类型名称,\n    i.REVENUE AS 营业收入,\n    i.REVENUEYOY AS 营业收入同比,\n    i.NETPROFIT AS 净利润,\n    i.NETPROFITYOY AS 净利润同比,\n    i.PAIDINCAPITAL AS 实收资本,\n    i.TOTALEQUITY AS 所有者权益合计,\n    i.ACCOUNTSRECEIVABLE AS 应收账款,\n    i.ARCHANGEFROMYEARSTART AS 应收账款较年初变动,\n    i.ARCHANGEFROMYEARSTARTRATE AS 应收账款较年初增幅,\n    i.OTHERRECEIVABLE AS 其他应收款,\n    i.ORCHANGEFROMYEARSTART AS 其他应收款较年初变动,\n    i.ORCHANGEFROMYEARSTARTRATE AS 其他应收款较年初增幅,\n    i.ARORTOTALASSETRATIO AS 应收账款和其他应收款合计占总资产比例,\n    i.SHORTLOAN AS 短期借款,\n    i.SHORTLOANCHANGEFROMYEARSTART AS 短期借款较年初变动,\n    i.SHORTLOANCHANGEFROMYEARSTARTRATE AS 短期借款较年初增幅,\n    i.LONGLOAN AS 长期借款,\n    i.LONGLOANCHANGEFROMYEARSTART AS 长期借款较年初变动,\n    i.LONGLOANCHANGEFROMYEARSTARTRATE AS 长期借款较年初增幅,\n    i.LONGLOANDUEWITHIN1Y AS 一年内到期的长期借款,\n    i.SALESLOANRATIO AS 销贷比,\n    i.NOTESPAYABLE AS 应付票据,\n    i.NOTESPAYABLECHANGEFROMYEARSTART AS 应付票据较年初变动,\n    i.NOTESPAYABLECHANGEFROMYEARSTARTRATE AS 应付票据较年初增幅,\n    i.OTHERPAYABLE AS 其他应付款,\n    i.OTHERPAYABLECHANGEFROMYEARSTART AS 其他应付款较年初变动,\n    i.OTHERPAYABLECHANGEFROMYEARSTARTRATE AS 其他应付款较年初增幅,\n    i.SLTOTALLOANYOY AS 短期借款和长期借款合计同比,\n    i.ARYOY AS 应收账款同比,\n    i.ARTURNOVERDAYS AS 应收账款周转天数,\n    i.INVENTORYTURNOVERDAYS AS 存货周转天数,\n    i.INVENTORYYOY AS 存货同比,\n    i.ACCOUNTSPAYABLE AS 应付账款,\n    i.INVENTORY AS 存货,\n    i.DEBTRATIO AS 资产负债率,\n    i.SALESPROFITRATIO AS 销售利率,\n    i.NETPROFITRATIO AS 净利率\nFROM APP_FINANCE_INDICATOR_INFO i\nWHERE i.REPORTNO = :reportNo\n  AND i.CUSTOMERNAME = :entName\n  AND i.REPORTSCOPE = ''本部''\n  AND i.subjectType=''借款人''\n  AND i.ACCOUNTMONTH::INTEGER = (\n      SELECT MAX(i2.ACCOUNTMONTH::INTEGER) - 100\n      FROM APP_FINANCE_INDICATOR_INFO i2\n      WHERE i2.REPORTNO = :reportNo\n        AND i2.CUSTOMERNAME = :entName\n  )\nORDER BY i.INPUTTIME DESC\nLIMIT 1","paramData":[{"id":"54b10e26-eac0-d8dd-0c52-1154a40f3c5a","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"6c7e9878-e4ba-ae73-4754-f3f5165bb750","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-14 20:19:26','admin',NULL,'2026-09-15 17:20:52',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2099473094654570497','REPORTSCOPE','报表口径','CHAR',NULL,NULL,'Y','N',NULL,'label',NULL,NULL,'2099473094558101506',NULL,'Public',NULL,'Auto','财务科目-最新一期合并','Public','1.0','3',NULL,NULL,NULL,'REPORTSCOPE','64','character varying',NULL,'是','报表口径（码值：合并/本部）','APP_FINANCE_INDICATOR_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-14 20:19:26','admin',NULL,'2026-09-14 20:19:26',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2099473094658764802','REPORTPERIOD','报表周期','CHAR',NULL,NULL,'Y','N',NULL,'label',NULL,NULL,'2099473094558101506',NULL,'Public',NULL,'Auto','财务科目-最新一期合并','Public','1.0','3',NULL,NULL,NULL,'REPORTPERIOD','64','character varying',NULL,'是','报表周期（码值：年报/半年报/季报/月报）','APP_FINANCE_INDICATOR_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-14 20:19:26','admin',NULL,'2026-09-14 20:19:26',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','',NULL,NULL),('2099493932292386817','gfcbycwtqxcfdqn','国发财报4指标-与财务同期值及相差幅度-前年','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2099492988448157697',NULL,'Public',NULL,'Auto','财务与其他交叉','Public','1.0','3',NULL,NULL,NULL,'APP_FINANCE_INDICATOR_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_FINANCE_INDICATOR_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    f.ACCOUNTMONTH AS 会计月,\n    g.BEFOREYEAR AS 国发前年日期,\n\n    f.REVENUE AS 财报营业收入,\n    g.BEFOREYEARREVENUE AS 国发营业收入,\n    ROUND(\n        ABS(f.REVENUE - g.BEFOREYEARREVENUE)\n        / NULLIF(ABS(f.REVENUE), 0) * 100,\n        2\n    ) AS 营业收入偏差幅度,\n\n    f.ACCOUNTSRECEIVABLE AS 财报应收账款,\n    g.BEFOREYEARRECEIVABLE AS 国发应收账款,\n    ROUND(\n        ABS(f.ACCOUNTSRECEIVABLE - g.BEFOREYEARRECEIVABLE)\n        / NULLIF(ABS(f.ACCOUNTSRECEIVABLE), 0) * 100,\n        2\n    ) AS 应收账款偏差幅度,\n\n    f.ACCOUNTSPAYABLE AS 财报应付账款,\n    g.BEFOREYEARPAYABLE AS 国发应付账款,\n    ROUND(\n        ABS(f.ACCOUNTSPAYABLE - g.BEFOREYEARPAYABLE)\n        / NULLIF(ABS(f.ACCOUNTSPAYABLE), 0) * 100,\n        2\n    ) AS 应付账款偏差幅度,\n\n    f.INVENTORY AS 财报存货,\n    g.BEFOREYEARINVENTORY AS 国发存货,\n    ROUND(\n        ABS(f.INVENTORY - g.BEFOREYEARINVENTORY)\n        / NULLIF(ABS(f.INVENTORY), 0) * 100,\n        2\n    ) AS 存货偏差幅度\n\nFROM APP_FINANCE_INDICATOR_INFO f\nLEFT JOIN APP_GUOFA_REPORT_INFO g\n    ON f.REPORTNO = g.REPORTNO\n    AND f.CUSTOMERID = g.CUSTOMERID\n    AND f.CUSTOMERNAME = g.CUSTOMERNAME\n    AND f.ACCOUNTMONTH = SUBSTRING(TRIM(g.BEFOREYEAR), 1, 6)\n    AND g.reportno = :reportNo\n    AND g.customername = :entName\n\nWHERE f.REPORTNO = :reportNo\n  AND f.CUSTOMERNAME = :entName\n  AND f.REPORTSCOPE = ''本部''\n  AND f.subjectType=''借款人''\n  AND f.ACCOUNTMONTH::INTEGER = (\n      SELECT\n          (FLOOR(MAX(f2.ACCOUNTMONTH::INTEGER) / 100) - 2) * 100 + 12\n      FROM APP_FINANCE_INDICATOR_INFO f2\n      WHERE f2.REPORTNO = :reportNo\n        AND f2.CUSTOMERNAME = :entName\n  AND f2.subjectType=''借款人''\n  )\nORDER BY f.INPUTTIME DESC\nLIMIT 1","paramData":[{"id":"54b10e26-eac0-d8dd-0c52-1154a40f3c5a","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"6c7e9878-e4ba-ae73-4754-f3f5165bb750","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-14 21:42:14','admin',NULL,'2026-09-15 17:26:32',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2099473094658764803','ID','ID','CHAR',NULL,NULL,'N','N',NULL,'label',NULL,NULL,'2099473094558101506',NULL,'Public',NULL,'Auto','财务科目-最新一期合并','Public','1.0','3',NULL,NULL,NULL,'ID','64,0','bigint',NULL,'否','','APP_FINANCE_INDICATOR_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-14 20:19:26','admin',NULL,'2026-09-14 20:19:26',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','',NULL,NULL),('2099473094662959105','REPORTNO','报告编号','CHAR',NULL,NULL,'N','N',NULL,'label',NULL,NULL,'2099473094558101506',NULL,'Public',NULL,'Auto','财务科目-最新一期合并','Public','1.0','3',NULL,NULL,NULL,'REPORTNO','64','character varying',NULL,'否','报告编号','APP_FINANCE_INDICATOR_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-14 20:19:26','admin',NULL,'2026-09-14 20:19:26',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','',NULL,NULL),