','Auto','国税-与财务同期值及相差幅度','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-14 21:16:43','admin','','2026-09-14 21:16:43',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2099387836944887810',NULL,0,'','','','','',NULL),('2099493652599418884','chpcfd','存货偏差幅度','CHAR',NULL,NULL,'Y','N',NULL,'label',NULL,NULL,'2099493652515532802',NULL,'Public',NULL,'Auto','财务科目-最新一期合并','Public','1.0','3',NULL,NULL,NULL,'INVENTORYTURNOVERDAYS','32,0','integer',NULL,'是','存货周转天数','APP_FINANCE_INDICATOR_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-14 21:41:08','admin',NULL,'2026-09-14 21:41:08',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2099486550187323393','gscbycwtqxcfdzx','国税财报4指标-与财务同期值及相差幅度-最新','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2099492988448157697',NULL,'Public',NULL,'Auto','财务与其他交叉','Public','1.0','3',NULL,NULL,NULL,'APP_FINANCE_INDICATOR_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_FINANCE_INDICATOR_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    f.ACCOUNTMONTH AS 会计月,\n    g.THISYEAR AS 国税最新一期日期,\n\n    f.REVENUE AS 财报营业收入,\n    g.GFREVENUE AS 国税营业收入,\n    ROUND(\n        ABS(f.REVENUE - g.GFREVENUE)\n        / NULLIF(ABS(f.REVENUE), 0) * 100,\n        2\n    ) AS 营业收入偏差幅度,\n\n    f.ACCOUNTSRECEIVABLE AS 财报应收账款,\n    g.GFRECEIVABLE AS 国税应收账款,\n    ROUND(\n        ABS(f.ACCOUNTSRECEIVABLE - g.GFRECEIVABLE)\n        / NULLIF(ABS(f.ACCOUNTSRECEIVABLE), 0) * 100,\n        2\n    ) AS 应收账款偏差幅度,\n\n    f.ACCOUNTSPAYABLE AS 财报应付账款,\n    g.GFPAYABLE AS 国税应付账款,\n    ROUND(\n        ABS(f.ACCOUNTSPAYABLE - g.GFPAYABLE)\n        / NULLIF(ABS(f.ACCOUNTSPAYABLE), 0) * 100,\n        2\n    ) AS 应付账款偏差幅度,\n\n    f.INVENTORY AS 财报存货,\n    g.GFINVENTORY AS 国税存货,\n    ROUND(\n        ABS(f.INVENTORY - g.GFINVENTORY)\n        / NULLIF(ABS(f.INVENTORY), 0) * 100,\n        2\n    ) AS 存货偏差幅度\n\nFROM APP_FINANCE_INDICATOR_INFO f\nLEFT JOIN APP_GS_FINANCE_DATA_INFO g\n    ON f.REPORTNO = g.REPORTNO\n    AND f.CUSTOMERID = g.CUSTOMERID\n    AND f.CUSTOMERNAME = g.CUSTOMERNAME\n    AND g.REPORTSCOPE = ''本部''\n    AND g.reportno = :reportNo\n    AND g.customername = :entName\nWHERE f.REPORTNO = :reportNo\n  AND f.CUSTOMERNAME = :entName\n  AND f.REPORTSCOPE = ''本部''\n  AND f.subjectType=''借款人''\n  AND f.ACCOUNTMONTH = (\n      SELECT MAX(f2.ACCOUNTMONTH)\n      FROM APP_FINANCE_INDICATOR_INFO f2\n      WHERE f2.REPORTNO = :reportNo\n        AND f2.CUSTOMERNAME = :entName\n          AND f2.subjectType=''借款人''\n  )\nLIMIT 1","paramData":[{"id":"54b10e26-eac0-d8dd-0c52-1154a40f3c5a","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"6c7e9878-e4ba-ae73-4754-f3f5165bb750","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-14 21:12:54','admin',NULL,'2026-09-15 17:28:42',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2099487507818229762','yfzkpcfd','应付账款偏差幅度','CHAR',NULL,NULL,'Y','N',NULL,'label',NULL,NULL,'2099487507734343681',NULL,'Public',NULL,'Auto','财务科目-最新一期合并','Public','1.0','3',NULL,NULL,NULL,'ARTURNOVERDAYS','32,0','integer',NULL,'是','应收账款周转天数','APP_FINANCE_INDICATOR_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-14 21:16:43','admin',NULL,'2026-09-14 21:16:43',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2099487507818229763','chpcfd','存货偏差幅度','CHAR',NULL,NULL,'Y','N',NULL,'label',NULL,NULL,'2099487507734343681',NULL,'Public',NULL,'Auto','财务科目-最新一期合并','Public','1.0','3',NULL,NULL,NULL,'INVENTORYTURNOVERDAYS','32,0','integer',NULL,'是','存货周转天数','APP_FINANCE_INDICATOR_INFO','2095447359636992001',NULL,'Sql',NULL,NULL,NULL,'admin',NULL,'2026-09-14 21:16:43','admin',NULL,'2026-09-14 21:16:43',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2099487507734343681','gscbycwtqxcfdsn','国税财报4指标-与财务同期值及相差幅度-上年','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2099492988448157697',NULL,'Public',NULL,'Auto','财务与其他交叉','Public','1.0','3',NULL,NULL,NULL,'APP_FINANCE_INDICATOR_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_FINANCE_INDICATOR_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    f.ACCOUNTMONTH AS 会计月,\n    g.LASTYEAR AS 国税去年日期,\n\n    f.REVENUE AS 财报营业收入,\n    g.LASTYEARREVENUE AS 国税营业收入,\n    ROUND(\n        ABS(f.REVENUE - g.LASTYEARREVENUE)\n        / NULLIF(ABS(f.REVENUE), 0) * 100,\n        2\n    ) AS 营业收入偏差幅度,\n\n    f.ACCOUNTSRECEIVABLE AS 财报应收账款,\n    g.LASTYEARRECEIVABLE AS 国税应收账款,\n    ROUND(\n        ABS(f.ACCOUNTSRECEIVABLE - g.LASTYEARRECEIVABLE)\n        / NULLIF(ABS(f.ACCOUNTSRECEIVABLE), 0) * 100,\n        2\n    ) AS 应收账款偏差幅度,\n\n    f.ACCOUNTSPAYABLE AS 财报应付账款,\n    g.LASTYEARPAYABLE AS 国税应付账款,\n    ROUND(\n        ABS(f.ACCOUNTSPAYABLE - g.LASTYEARPAYABLE)\n        / NULLIF(ABS(f.ACCOUNTSPAYABLE), 0) * 100,\n        2\n    ) AS 应付账款偏差幅度,\n\n    f.INVENTORY AS 财报存货,\n    g.LASTYEARINVENTORY AS 国税存货,\n    ROUND(\n        ABS(f.INVENTORY - g.LASTYEARINVENTORY)\n        / NULLIF(ABS(f.INVENTORY), 0) * 100,\n        2\n    ) AS 存货偏差幅度\n\nFROM APP_FINANCE_INDICATOR_INFO f\nLEFT JOIN APP_GS_FINANCE_DATA_INFO g\n    ON f.REPORTNO = g.REPORTNO\n    AND f.CUSTOMERID = g.CUSTOMERID\n    AND f.CUSTOMERNAME = g.CUSTOMERNAME\n    AND g.REPORTSCOPE = ''本部''\n    AND f.ACCOUNTMONTH = SUBSTRING(TRIM(g.LASTYEAR), 1, 6)\n    AND g.reportno = :reportNo\n    AND g.customername = :entName\n\nWHERE \n   f.REPORTSCOPE = ''本部''\n  AND f.subjectType=''借款人''\n  AND f.ACCOUNTMONTH::INTEGER = (\n      SELECT\n          (FLOOR(MAX(f2.ACCOUNTMONTH::INTEGER) / 100) - 1) * 100 + 12\n      FROM APP_FINANCE_INDICATOR_INFO f2\n      WHERE \n       f2.subjectType=''借款人''\n  AND f2.reportno = :reportNo\n  AND f2.customername = :entName\n  )\n  AND f.reportno = :reportNo\n  AND f.customername = :entName\nORDER BY f.INPUTTIME DESC\nLIMIT 1","paramData":[{"id":"54b10e26-eac0-d8dd-0c52-1154a40f3c5a","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"6c7e9878-e4ba-ae73-4754-f3f5165bb750","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-14 21:16:43','admin',NULL,'2026-09-15 17:28:11',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2099492014430105601','gscbycwtqxcfdqn','国税财报4指标-与财务同期值及相差幅度-前年','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2099492988448157697',NULL,'Public',NULL,'Auto','财务与其他交叉','Public','1.0','3',NULL,NULL,NULL,'APP_FINANCE_INDICATOR_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_FINANCE_INDICATOR_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    f.ACCOUNTMONTH AS 会计月,\n    g.BEFOREYEAR AS 国税前年日期,\n\n    f.REVENUE AS 财报营业收入,\n    g.BEFOREYEARREVENUE AS 国税营业收入,\n    ROUND(\n        ABS(f.REVENUE - g.BEFOREYEARREVENUE)\n        / NULLIF(ABS(f.REVENUE), 0) * 100,\n        2\n    ) AS 营业收入偏差幅度,\n\n    f.ACCOUNTSRECEIVABLE AS 财报应收账款,\n    g.BEFOREYEARRECEIVABLE AS 国税应收账款,\n    ROUND(\n        ABS(f.ACCOUNTSRECEIVABLE - g.BEFOREYEARRECEIVABLE)\n        / NULLIF(ABS(f.ACCOUNTSRECEIVABLE), 0) * 100,\n        2\n    ) AS 应收账款偏差幅度,\n\n    f.ACCOUNTSPAYABLE AS 财报应付账款,\n    g.BEFOREYEARPAYABLE AS 国税应付账款,\n    ROUND(\n        ABS(f.ACCOUNTSPAYABLE - g.BEFOREYEARPAYABLE)\n        / NULLIF(ABS(f.ACCOUNTSPAYABLE), 0) * 100,\n        2\n    ) AS 应付账款偏差幅度,\n\n    f.INVENTORY AS 财报存货,\n    g.BEFOREYEARINVENTORY AS 国税存货,\n    ROUND(\n        ABS(f.INVENTORY - g.BEFOREYEARINVENTORY)\n        / NULLIF(ABS(f.INVENTORY), 0) * 100,\n        2\n    ) AS 存货偏差幅度\n\nFROM APP_FINANCE_INDICATOR_INFO f\nLEFT JOIN APP_GS_FINANCE_DATA_INFO g\n    ON f.REPORTNO = g.REPORTNO\n    AND f.CUSTOMERID = g.CUSTOMERID\n    AND f.CUSTOMERNAME = g.CUSTOMERNAME\n    AND g.REPORTSCOPE = ''本部''\n    AND f.ACCOUNTMONTH = SUBSTRING(TRIM(g.BEFOREYEAR), 1, 6)\n    AND g.reportno = :reportNo\n    AND g.customername = :entName\n\nWHERE f.REPORTNO = :reportNo\n  AND f.CUSTOMERNAME = :entName\n  AND f.REPORTSCOPE = ''本部''\n  AND f.subjectType=''借款人''\n  AND f.ACCOUNTMONTH::INTEGER = (\n      SELECT\n          (FLOOR(MAX(f2.ACCOUNTMONTH::INTEGER) / 100) - 2) * 100 + 12\n      FROM APP_FINANCE_INDICATOR_INFO f2\n      WHERE f2.REPORTNO = :reportNo\n        AND f2.CUSTOMERNAME = :entName\n  AND f2.subjectType=''借款人''\n  )\nORDER BY f.INPUTTIME DESC\nLIMIT 1","paramData":[{"id":"54b10e26-eac0-d8dd-0c52-1154a40f3c5a","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"6c7e9878-e4ba-ae73-4754-f3f5165bb750","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-14 21:34:37','admin',NULL,'2026-09-15 17:27:20',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2099492014505603074','yszkpcfd','应收账款偏差幅度','CHAR','','','','Y','','label','','','2099492014430105601','','Public','','Auto','国税-与财务同期值及相差幅度-最新','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','',NULL,NULL,'admin','','2026-09-14 21:34:37','admin','','2026-09-14 21:34:37',NULL,NULL,NUL