me","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-14 19:48:56','admin',NULL,'2026-09-15 10:21:17',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2099493652515532802','gfcbycwtqxcfdzx','国发财报4指标-与财务同期值及相差幅度-最新','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2099492988448157697',NULL,'Public',NULL,'Auto','财务与其他交叉','Public','1.0','3',NULL,NULL,NULL,'APP_FINANCE_INDICATOR_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_FINANCE_INDICATOR_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    f.ACCOUNTMONTH AS 会计月,\n    g.THISYEAR AS 国发最新一期日期,\n\n    f.REVENUE AS 财报营业收入,\n    g.GFREVENUE AS 国发营业收入,\n    ROUND(\n        ABS(f.REVENUE - g.GFREVENUE)\n        / NULLIF(ABS(f.REVENUE), 0) * 100,\n        2\n    ) AS 营业收入偏差幅度,\n\n    f.ACCOUNTSRECEIVABLE AS 财报应收账款,\n    g.GFRECEIVABLE AS 国发应收账款,\n    ROUND(\n        ABS(f.ACCOUNTSRECEIVABLE - g.GFRECEIVABLE)\n        / NULLIF(ABS(f.ACCOUNTSRECEIVABLE), 0) * 100,\n        2\n    ) AS 应收账款偏差幅度,\n\n    f.ACCOUNTSPAYABLE AS 财报应付账款,\n    g.GFPAYABLE AS 国发应付账款,\n    ROUND(\n        ABS(f.ACCOUNTSPAYABLE - g.GFPAYABLE)\n        / NULLIF(ABS(f.ACCOUNTSPAYABLE), 0) * 100,\n        2\n    ) AS 应付账款偏差幅度,\n\n    f.INVENTORY AS 财报存货,\n    g.GFINVENTORY AS 国发存货,\n    ROUND(\n        ABS(f.INVENTORY - g.GFINVENTORY)\n        / NULLIF(ABS(f.INVENTORY), 0) * 100,\n        2\n    ) AS 存货偏差幅度\n\nFROM APP_FINANCE_INDICATOR_INFO f\nLEFT JOIN APP_GUOFA_REPORT_INFO g\n    ON f.REPORTNO = g.REPORTNO\n    AND f.CUSTOMERID = g.CUSTOMERID\n    AND f.CUSTOMERNAME = g.CUSTOMERNAME\n    AND f.ACCOUNTMONTH = SUBSTRING(TRIM(g.THISYEAR), 1, 6)\n    AND g.reportno = :reportNo\n    AND g.customername = :entName\n\nWHERE f.REPORTNO = :reportNo\n  AND f.CUSTOMERNAME = :entName\n  AND f.REPORTSCOPE = ''本部''\n  AND f.subjectType=''借款人''\n  AND f.ACCOUNTMONTH = (\n      SELECT MAX(f2.ACCOUNTMONTH)\n      FROM APP_FINANCE_INDICATOR_INFO f2\n      WHERE f2.REPORTNO = :reportNo\n        AND f2.CUSTOMERNAME = :entName\n  AND f2.subjectType=''借款人''\n  )\nORDER BY f.INPUTTIME DESC\nLIMIT 1","paramData":[{"id":"54b10e26-eac0-d8dd-0c52-1154a40f3c5a","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"6c7e9878-e4ba-ae73-4754-f3f5165bb750","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-14 21:41:08','admin',NULL,'2026-09-15 17:26:56',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2099494367401095170','gfcbycwtqxcfdsn_copy','国发财报4指标-与财务同期值及相差幅度-上年','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2099492988448157697',NULL,'Public',NULL,'Auto','财务与其他交叉','Public','1.0','3',NULL,NULL,NULL,'APP_FINANCE_INDICATOR_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_FINANCE_INDICATOR_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    f.ACCOUNTMONTH AS 会计月,\n    g.LASTYEAR AS 国发去年日期,\n\n    f.REVENUE AS 财报营业收入,\n    g.LASTYEARREVENUE AS 国发营业收入,\n    ROUND(\n        ABS(f.REVENUE - g.LASTYEARREVENUE)\n        / NULLIF(ABS(f.REVENUE), 0) * 100,\n        2\n    ) AS 营业收入偏差幅度,\n\n    f.ACCOUNTSRECEIVABLE AS 财报应收账款,\n    g.LASTYEARRECEIVABLE AS 国发应收账款,\n    ROUND(\n        ABS(f.ACCOUNTSRECEIVABLE - g.LASTYEARRECEIVABLE)\n        / NULLIF(ABS(f.ACCOUNTSRECEIVABLE), 0) * 100,\n        2\n    ) AS 应收账款偏差幅度,\n\n    f.ACCOUNTSPAYABLE AS 财报应付账款,\n    g.LASTYEARPAYABLE AS 国发应付账款,\n    ROUND(\n        ABS(f.ACCOUNTSPAYABLE - g.LASTYEARPAYABLE)\n        / NULLIF(ABS(f.ACCOUNTSPAYABLE), 0) * 100,\n        2\n    ) AS 应付账款偏差幅度,\n\n    f.INVENTORY AS 财报存货,\n    g.LASTYEARINVENTORY AS 国发存货,\n    ROUND(\n        ABS(f.INVENTORY - g.LASTYEARINVENTORY)\n        / NULLIF(ABS(f.INVENTORY), 0) * 100,\n        2\n    ) AS 存货偏差幅度\n\nFROM APP_FINANCE_INDICATOR_INFO f\nLEFT JOIN APP_GUOFA_REPORT_INFO g\n    ON f.REPORTNO = g.REPORTNO\n    AND f.CUSTOMERID = g.CUSTOMERID\n    AND f.CUSTOMERNAME = g.CUSTOMERNAME\n    AND f.ACCOUNTMONTH = SUBSTRING(TRIM(g.LASTYEAR), 1, 6)\n    AND g.reportno = :reportNo\n    AND g.customername = :entName\n\nWHERE f.REPORTNO = :reportNo\n  AND f.CUSTOMERNAME = :entName\n  AND f.REPORTSCOPE = ''本部''\n  AND f.subjectType=''借款人''\n  AND f.ACCOUNTMONTH::INTEGER = (\n      SELECT\n          (FLOOR(MAX(f2.ACCOUNTMONTH::INTEGER) / 100) - 1) * 100 + 12\n      FROM APP_FINANCE_INDICATOR_INFO f2\n      WHERE f2.REPORTNO = :reportNo\n        AND f2.CUSTOMERNAME = :entName\n  AND f2.subjectType=''借款人''\n  )\nORDER BY f.INPUTTIME DESC\nLIMIT 1","paramData":[{"id":"54b10e26-eac0-d8dd-0c52-1154a40f3c5a","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"6c7e9878-e4ba-ae73-4754-f3f5165bb750","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-14 21:43:58','admin',NULL,'2026-09-15 17:26:06',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2099504086844977154','zxycwjc','征信与财务交叉','LIST','','','','Y','','label','','','2095329761296400386','','Public','','Auto','征信情况','Public','','','',NULL,'','','','','','','','','',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    c.ID AS ID,\n    c.REPORTNO AS 报告编号,\n    c.CUSTOMERID AS 客户编号,\n    c.CUSTOMERNAME AS 客户名称,\n    c.QUERYTIME AS 征信查询时间,\n\n    f.ACCOUNTMONTH AS 会计月,\n\n    f.SHORTLOAN AS 财报短期借款,\n    c.SHORTTERMLOANBAL AS 征信短期借款未结清余额,\n    ROUND(\n        c.SHORTTERMLOANBAL - f.SHORTLOAN,\n        2\n    ) AS 征信短期借款相差,\n\n    f.LONGLOAN AS 财报长期借款,\n    f.LONGLOANDUEWITHIN1Y AS 一年内到期长期借款,\n    c.MIDLONGTERMLOANBAL AS 征信中长期借款未结清余额,\n    ROUND(\n        c.MIDLONGTERMLOANBAL\n        - COALESCE(f.LONGLOAN, 0)\n        - COALESCE(f.LONGLOANDUEWITHIN1Y, 0),\n        2\n    ) AS 征信中长期借款相差,\n\n    ROUND(\n        ABS(\n            COALESCE(c.SHORTTERMLOANBAL, 0)\n            + COALESCE(c.MIDLONGTERMLOANBAL, 0)\n            - COALESCE(f.SHORTLOAN, 0)\n            - COALESCE(f.LONGLOAN, 0)\n            - COALESCE(f.LONGLOANDUEWITHIN1Y, 0)\n        )\n        / NULLIF(\n            ABS(\n                COALESCE(f.SHORTLOAN, 0)\n                + COALESCE(f.LONGLOAN, 0)\n                + COALESCE(f.LONGLOANDUEWITHIN1Y, 0)\n            ),\n            0\n        ) * 100,\n        2\n    ) AS 征信债务偏离度,\n\n    c.GUARANTEEBALANCEEXBANK AS 对外担保余额（剔除我行）,\n    f.TOTALEQUITY AS 所有者权益,\n\n    ROUND(\n        c.GUARANTEEBALANCEEXBANK\n        / NULLIF(f.TOTALEQUITY, 0) * 100,\n        2\n    ) AS 对外担保净资产比\n\nFROM APP_CREDIT_REPORT_INFO c\n\nINNER JOIN APP_FINANCE_INDICATOR_INFO f\n    ON f.REPORTNO = c.REPORTNO\n    AND f.CUSTOMERID = c.CUSTOMERID\n    AND f.CUSTOMERNAME = c.CUSTOMERNAME\n    AND f.GUARANTORID = c.GUARANTORID\n    AND f.GUARANTORNAME = c.GUARANTORNAME\n    AND f.REPORTSCOPE = ''本部''\n    AND f.reportno = :reportNo\n    AND f.customername = :entName\n\nWHERE c.REPORTNO = :reportNo\n  AND c.CUSTOMERNAME = :entName\n  AND c.GUARANTORNAME = :guarantorName\n\n  AND f.ACCOUNTMONTH = (\n      SELECT MAX(f2.ACCOUNTMONTH)\n      FROM APP_FINANCE_INDICATOR_INFO f2\n      WHERE f2.REPORTNO = c.REPORTNO\n        AND f2.CUSTOMERID = c.CUSTOMERID\n        AND f2.CUSTOMERNAME = c.CUSTOMERNAME\n        AND f2.GUARANTORID = c.GUARANTORID\n        AND f2.GUARANTORNAME = c.GUARANTORNAME\n        AND f2.REPORTSCOPE = ''本部''\n  AND f2.reportno = :reportNo\n  AND f2.customername = :entName\n  )\n\n  AND c.QUERYTIME >= TO_DATE(f.ACCOUNTMONTH || ''01'', ''YYYYMMDD'')\n  AND c.QUERYTIME < ADD_MONTHS(\n      TO_DATE(f.ACCOUNTMONTH || ''01'', ''YYYYMMDD''),\n      4\n  )\n\nLIMIT 1","paramData":[{"id":"2a9152b1-8542-a0db-0c17-d11b59c4d460","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"bd138d27-b35d-1604-20e3-ac40f629e622","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null},{"id":"63fa1a6a-7dec-c102-848f-8cd76318565c","name":"guarantorName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin','','2026-09-14 22:22:35','admin','','2026-09-14 22:46:48',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2095329761296400386',NULL,0,'','','','','',NULL),('2097876297423269889','danxingjianca','单项检查任务','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2097875968526921730',NULL,'Public',NULL,'Auto','现场打卡','Public','1.0','3',NULL,NULL,NULL,'APP_CREDIT_USE_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_CREDIT_USE_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    i.ID AS ID,\n    i.REPORTNO AS 报告编号,\n    i.CUSTOMERID AS 客户编号,\n    i.CUSTOMERNAME AS 客户名称,\n    i.INPUTTIME AS 入库时间,\n    i.SERIALNO AS 单项检查任务流水号,\n    i.CREDITNO AS 授信编号,\n    i.APPROVETEXTNO AS 批复编号,\n    i.STARTDATE AS 批复生效日期,\n    i.MATURITY AS 批复到期日,\n    i.GROUPNAME AS 集团名称,\n    i.PRODUCTNAME AS 对象,\n    i.approveStatusName AS 审批状态,\n    i.CHECKDATE AS 检查时间,\n    i.BALANCE AS 对象项下借据余额,\n    i.CONDITION AS 批复后续管理要求,\n    i.ITEMCATEGORY AS 事项类别,\n    i.IMPLEMENTSTATUS AS 落实情况,\n    i.EXTENDDATE AS 延期日期,\n    i.OPINION AS 签署意见,\n    i.CONDITIONINSTRUCTION AS 情况说明,\n    i.CREDITAPPROVEUSERNAME AS 授信审查人,\n    i.APPROVEAUTHOR AS 审批权限,\n    i.OPERATEBELONGORGNAME AS 分行,\n    i.OPERATEORGNAME AS 支行,\n    i.OPERATEUSERNAME AS 经办客户经理\nFROM app_single_check_task_info i\nWHERE i.REPORTNO = :reportNo\nAND i.CUSTOMERNAME = :entName","paramData":[{"id":"9cc31f8b-c0ce-4fbd-bab0-40613d884008","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"cfe523ee-9c4e-4fe4-165e-89fc654715dd","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-10 10:34:20','admin',NULL,'2026-09-15 14:01:36',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2099391513457864705','app_gs_tax_sales_info_sn','国税-与财务同期值及相差幅度-上年','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2099492988448157697',NULL,'Public',NULL,'Auto','财务与其他交叉','Public','1.0','3',NULL,NULL,NULL,'APP_FINANCE_INDICATOR_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_FINANCE_INDICATOR_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    t.ID AS ID,\n    t.REPORTNO AS 报告编号,\n    t.CUSTOMERID AS 客户编号,\n    t.CUSTOMERNAME AS 客户名称,\n    t.INPUTTIME AS 入库时间,\n    t.TAXPERIOD AS 纳税期,\n    t.MONTHLYTAXSALES AS 每月纳税销售额,\n    t.TOTALSALESTAX AS 当年纳税销售额累计,\n    t.YOYCHANGE AS 当年销售额较上年同期变动额,\n    t.YOYRATE AS 当年销售额较上年同期同比,\n    ''上年12月'' AS 时间类型,\n    f.REVENUE AS 营业收入,\n  ROUND(\n        ABS(t.TOTALSALESTAX - f.REVENUE),\n        2\n    ) AS 纳税申报销售总额与当期报表相差金额,\n    ROUND(\n        ABS(t.TOTALSALESTAX - f.REVENUE)\n        / NULLIF(f.REVENUE, 0) * 100,\n        2\n    ) AS 纳税申报销售总额与当期报表相差幅度\nFROM APP_GS_TAX_SALES_INFO t\nCROSS JOIN (\n    SELECT\n        MAX(ACCOUNTMONTH) AS MAX_MONTH\n    FROM APP_FINANCE_INDICATOR_INFO\n    WHERE REPORTNO = :reportNo\n    AND CUSTOMERNAME = :entName\n) m\nLEFT JOIN APP_FINANCE_INDICATOR_INFO f\n    ON f.REPORTNO = t.REPORTNO\n    AND f.CUSTOMERID = t.CUSTOMERID\n    AND f.CUSTOMERNAME = t.CUSTOMERNAME\n    AND f.REPORTSCOPE = ''本部''\n  AND f.subjectType=''借款人''\n    AND f.ACCOUNTMONTH = t.TAXPERIOD\n    AND f.reportno = :reportNo\n    AND f.customername = :entName\nWHERE t.REPORTNO = :reportNo\nAND t.CUSTOMERNAME = :entName\nAND t.TAXPERIOD = (m.MAX_MONTH - (m.MAX_MONTH % 100)) - 88\n  AND f.REPORTPERIOD = ''年报''","paramData":[{"id":"54b10e26-eac0-d8dd-0c52-1154a40f3c5a","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"6c7e9878-e4ba-ae73-4754-f3f5165bb750","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-14 14:55:16','admin',NULL,'2026-09-15 17:29:24',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),('2099387836944887810','app_gs_tax_sales_info_zx','国税-与财务同期值及相差幅度-最新','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2099492988448157697',NULL,'Public',NULL,'Auto','财务与其他交叉','Public','1.0','3',NULL,NULL,NULL,'APP_FINANCE_INDICATOR_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_FINANCE_INDICATOR_INFO','2095447359636992001',NULL,'Sql','{"dataSource":"2095447359636992001","sql":"SELECT\n    t.ID AS ID,\n    t.REPORTNO AS 报告编号,\n    t.CUSTOMERID AS 客户编号,\n    t.CUSTOMERNAME AS 客户名称,\n    t.TAXPERIOD AS 纳税期,\n    t.MONTHLYTAXSALES AS 每月纳税销售额,\n    t.TOTALSALESTAX AS 当年纳税销售额累计,\n    t.YOYCHANGE AS 当年销售额较上年同期变动额,\n    t.YOYRATE AS 当年销售额较上年同期同比,\n    ''最新一期'' AS 时间类型,\n    f.REVENUE AS 营业收入,\n    ROUND(\n        ABS(t.TOTALSALESTAX - f.REVENUE),\n        2\n    ) AS 纳税申报销售总额与当期报表相差金额,\n    ROUND(\n        ABS(t.TOTALSALESTAX - f.REVENUE)\n        / NULLIF(f.REVENUE, 0) * 100,\n        2\n    ) AS 纳税申报销售总额与当期报表相差幅度\nFROM APP_GS_TAX_SALES_INFO t\nCROSS JOIN (\n    SELECT\n        MAX(ACCOUNTMONTH) AS MAX_MONTH\n    FROM APP_FINANCE_INDICATOR_INFO\n    WHERE REPORTNO = :reportNo\n    AND CUSTOMERNAME = :entName\n) m\nLEFT JOIN APP_FINANCE_INDICATOR_INFO f\n    ON f.REPORTNO = t.REPORTNO\n    AND f.CUSTOMERID = t.CUSTOMERID\n    AND f.CUSTOMERNAME = t.CUSTOMERNAME\n    AND f.REPORTSCOPE = ''本部''\n  AND f.subjectType=''借款人''\n    AND f.ACCOUNTMONTH = t.TAXPERIOD\n    AND f.reportno = :reportNo\n    AND f.customername = :entName\nWHERE t.REPORTNO = :reportNo\nAND t.CUSTOMERNAME = :entName\nAND t.TAXPERIOD = m.MAX_MONTH","paramData":[{"id":"54b10e26-eac0-d8dd-0c52-1154a40f3c5a","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"6c7e9878-e4ba-ae73-4754-f3f5165bb750","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-14 14:40:39','admin',NULL,'2026-09-15 17:29:35',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL);
